  const after = procStat(await readFile(base + '/stat', 'utf8'));
  if (before.procPid !== after.procPid || before.startTicks !== after.startTicks ||
      before.parentProcPid !== after.parentProcPid)
    throw new Error('PROCESS_IDENTITY_CHANGED');
