    manifest.schema===SOURCE_SCHEMA&&manifest.runtimeDirectory===directory&&
    Array.isArray(manifest.files)&&manifest.files.length>0&&manifest.files.length<=10000,
    'CONTINUATION_RUNTIME_MANIFEST_INVALID');
