    need(keys(entry,['path','bytes','sha256'])&&Number.isSafeInteger(entry.bytes)&&entry.bytes>=0&&
      entry.bytes<=MAX_FILE&&HASH.test(entry.sha256??''),'CONTINUATION_RUNTIME_FILE_INVALID');
