  need(typeof reason === 'string' && reason === reason.trim() && reason.length > 0 &&
    reason.length <= 1000 && !/[\x00-\x1f\x7f]/.test(reason), 'UNPAID_CONTINUATION_REMEDIATION_REQUIRED');
