// authenticated browser, revision reports and both original portable readers.
import {parseArgs} from 'node:util';
import {resolve,join,isAbsolute,relative,sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {lstat} from 'node:fs/promises';
import {openDossierStore} from './dossier.mjs';
import {startDossierWorkspace} from './server.mjs';
import {validateCrossrefEdition} from './crossref.mjs';
import {validateCrossrefDocumentEdition} from './crossref-documents.mjs';
import {citationDigest} from './citation-updates.mjs';
import {readResearchHostFile} from './workspace-files.mjs';
import {openPortableFile,writePortableFile} from './portable.mjs';
import {privateDirectory,writeJson,readJson,writeBytes,readBytes,parseJson,jsonBytes,digest,need,object} from '../node/store.mjs';

const SCHEMA='sf88-citation-review-workflow.v1';
const MAX_SOURCE=64*1024*1024,MAX_PORTABLE=256*1024*1024;
const exists=async file=>{try{const value=await lstat(file);need(value.isFile()&&!value.isSymbolicLink(),'WORKFLOW_FILE_INVALID');return true;}
  catch(error){if(error.code==='ENOENT')return false;throw error;}};
const optionalJson=async file=>await exists(file)?readJson(file,16*1024*1024):null;
const same=(left,right)=>citationDigest(left)===citationDigest(right);
async function immutableBytes(file,bytes){
  if(await exists(file)){
    const existing=await readBytes(file,MAX_PORTABLE);
    need(existing.length===bytes.length&&digest(existing)===digest(bytes),'WORKFLOW_ARTIFACT_CHANGED');return;
  }
  try{await writeBytes(file,bytes,{exclusive:true});}
  catch(error){if(error.code!=='EEXIST')throw error;const saved=await readBytes(file,MAX_PORTABLE);
    need(saved.length===bytes.length&&digest(saved)===digest(bytes),'WORKFLOW_ARTIFACT_CHANGED');}
}
async function identity(file){
  const body=await readResearchHostFile(file,MAX_PORTABLE);
  return {file,bytes:body.length,sha256:digest(body)};
}
async function notices(store,id,revision){
  const rows=[];let offset=0;
  while(true){
    const page=await store.citationUpdates(id,{revision,offset,limit:100});
    rows.push(...page.items);
    if(page.nextOffset===null)return rows;offset=page.nextOffset;
  }
}
async function selectNotice(store,id,revision,targetDoi){
  const rows=await notices(store,id,revision);
  for(const row of rows){
    if(targetDoi&&row.targetDoi!==targetDoi)continue;
    const detail=await store.citationUpdates(id,{revision,noticeId:row.noticeId});
    if(detail.detail.evidence.length)return detail.detail;
  }
  need(false,'WORKFLOW_RETAINED_NOTICE_AND_TARGET_REQUIRED');
}

async function prepare({store,runDirectory,binding,raw,targetDoi}){
  const file=join(runDirectory,'seed.json'),existing=await optionalJson(file);
  if(existing){need(same(existing.binding,binding),'WORKFLOW_INPUT_CHANGED');
    const saved=await store.getMetadata(existing.dossierId,{revision:existing.originalRevision});
    need(saved.revision===existing.originalRevision,'WORKFLOW_SEED_CHANGED');return existing;}
  const title='Citation update review / '+binding.operation;
  const matches=(await store.list()).filter(value=>value.title===title);
  need(matches.length<=1,'WORKFLOW_DOSSIER_AMBIGUOUS');
  let metadata=matches.length?await store.getMetadata(matches[0].id):
    await store.create({title,description:'Review the original registered notice and its source use across two research questions.',
      projection:'metadata'});
  const id=metadata.id,questionTexts=[
    'How does the registered notice affect this publication in the primary evidence review?',
    'How should the same publication be used in the related evidence summary?'
  ];
  const questionIds=[];
  for(const questionText of questionTexts){
    let rows=metadata.questions.filter(value=>value.text===questionText);
    need(rows.length<=1,'WORKFLOW_QUESTION_AMBIGUOUS');
    if(!rows.length){metadata=await store.addQuestion(id,{text:questionText,expectedRevision:metadata.revision,projection:'metadata'});
      rows=metadata.questions.filter(value=>value.text===questionText);}
    const question=rows[0];questionIds.push(question.id);
    metadata=await store.receive(id,{questionId:question.id,label:'Original registered notice and work metadata',
      provider:binding.provider,rawBytes:raw,sourceReference:binding.sourceReference,
      origin:{mode:'citation-review-workflow',operation:binding.operation,inputSha256:binding.editionSha256},
      expectedRevision:metadata.revision,projection:'metadata'});
  }
  let notice=await selectNotice(store,id,metadata.revision,targetDoi);
  const view=await store.get(id,{revision:metadata.revision,references:false,includeHistory:false});
  const source=view.sources.find(value=>value.doi===notice.targetDoi);
  need(source,'WORKFLOW_TARGET_SOURCE_REQUIRED');
  const note='Selected for review against registered notice '+notice.noticeDoi+'.';
  const currentSelections=notice.evidence.filter(value=>questionIds.includes(value.questionId));
  if(currentSelections.some(value=>!value.selected||value.classification!=='background'||value.note!==note))
    metadata=await store.selectEvidence(id,{sourceId:source.id,selected:true,classification:'background',note,
      expectedRevision:metadata.revision,projection:'metadata'});
  for(const [index,questionId]of questionIds.entries()){
    const findingTitle='Citation assessment / question '+(index+1);
    const rows=metadata.findings.filter(value=>value.questionId===questionId&&value.title===findingTitle);
    need(rows.length<=1,'WORKFLOW_FINDING_AMBIGUOUS');
    if(!rows.length)metadata=await store.addFinding(id,{questionId,title:findingTitle,
      text:'The source '+notice.targetDoi+' is retained in this evidence review. Its registered '+notice.type+
        ' notice '+notice.noticeDoi+' requires an explicit decision about the source use and citation.',
      sourceIds:[source.id],expectedRevision:metadata.revision,projection:'metadata'});
  }
  notice=(await store.citationUpdates(id,{revision:metadata.revision,noticeId:notice.noticeId})).detail;
  need(notice.findings.length===2&&notice.evidence.filter(value=>value.selected).length===2,
    'WORKFLOW_SOURCE_JOIN_INCOMPLETE');
  const seed={schema:SCHEMA,binding,dossierId:id,noticeId:notice.noticeId,noticeDoi:notice.noticeDoi,
    targetDoi:notice.targetDoi,sourceId:source.id,questionIds,findingIds:notice.findings.map(value=>value.id),
    originalRevision:metadata.revision,originalFingerprint:notice.fingerprint,preparedAt:new Date().toISOString()};
  try{await writeJson(file,seed,{exclusive:true});}catch(error){if(error.code!=='EEXIST')throw error;
    const saved=await readJson(file,1024*1024);need(same(saved,seed),'WORKFLOW_SEED_CHANGED');}
  return seed;
}

async function portable({store,id,revision,file,compression}){
  if(!(await exists(file)))await writePortableFile(file,await store.exportStream(id,{revision,compression}));
  return identity(file);
}
async function reports({store,id,selection,directory}){
  const artifacts=[];
  for(const [label,revision]of [['original',selection.originalRevision],['reviewed',selection.reviewedRevision],
    ['current',selection.currentRevision]]){
    for(const format of ['md','html']){
      const exported=await store.exportDossier(id,{format,revision});
      need(exported.revision===revision,'WORKFLOW_REPORT_REVISION_CHANGED');
      const file=join(directory,label+'-r'+revision+'.'+format);
      await immutableBytes(file,Buffer.from(exported.body));
      artifacts.push({...await identity(file),kind:'report',revision,format});
    }
  }
  artifacts.push({...await portable({store,id,revision:selection.currentRevision,
    file:join(directory,'complete.research.json'),compression:'none'}),kind:'portable',format:'json',
    revision:selection.currentRevision});
  artifacts.push({...await portable({store,id,revision:selection.currentRevision,
    file:join(directory,'complete.research.json.gz'),compression:'gzip'}),kind:'portable',format:'json.gz',
    revision:selection.currentRevision});
  return artifacts;
}
async function verifyReopened({original,received,id,selection,noticeId,rawSha256}){
  const left=await original.getMetadata(id,{revision:selection.currentRevision});
  const right=await received.getMetadata(id,{revision:selection.currentRevision});
  need(same(left,right),'WORKFLOW_REOPENED_METADATA_CHANGED');
  const leftDetail=await original.citationUpdates(id,{revision:selection.currentRevision,noticeId});
  const rightDetail=await received.citationUpdates(id,{revision:selection.currentRevision,noticeId});
  need(same(leftDetail,rightDetail),'WORKFLOW_REOPENED_REVIEW_CHANGED');
  need(rightDetail.detail.reviews.some(value=>value.id===selection.reviewId),'WORKFLOW_REVIEW_MISSING');
  const bodies=[];
  for(const edition of left.editions.filter(value=>value.mode==='retained')){
    const source=await original.readRetainedEdition(id,edition.id,{revision:selection.currentRevision});
    const copy=await received.readRetainedEdition(id,edition.id,{revision:selection.currentRevision});
    need(source.bytes.equals(copy.bytes),'WORKFLOW_REOPENED_SOURCE_CHANGED');
    bodies.push({editionId:edition.id,bytes:copy.bytes.length,sha256:digest(copy.bytes)});
  }
  need(bodies.some(value=>value.sha256===rawSha256),'WORKFLOW_ORIGINAL_SOURCE_MISSING');
  for(const revision of [...new Set([selection.originalRevision,selection.reviewedRevision,selection.currentRevision])]){
    for(const format of ['md','html']){
      const a=await original.exportDossier(id,{revision,format});
      const b=await received.exportDossier(id,{revision,format});
      need(a.body===b.body,'WORKFLOW_REOPENED_REPORT_CHANGED');
    }
  }
  return {dossierId:id,revision:right.revision,reviewId:selection.reviewId,
    sourceBodies:bodies,status:rightDetail.detail.status};
}
async function rejectAlteredReview({portableFile,selection,runDirectory}){
  const incoming=parseJson(await readBytes(portableFile,MAX_PORTABLE));
  let changed=0,previous=null;
  for(const envelope of incoming.versions){
    const review=envelope.state.citationReviews?.find(value=>value.id===selection.reviewId);
    if(review){
      // Keep the saved request unchanged and change only its claimed original
      // source occurrence. Rehash the review and outer history so rejection
      // exercises source replay, rather than a broken transport checksum.
      review.notice.latestSource.key='999999';
      review.notice.latestSource.occurrenceId='o_'+digest(Buffer.from(
        review.notice.latestSource.editionId+'\n'+review.notice.latestSource.key));
      const {sha256,...payload}=review;review.sha256=citationDigest(payload);changed++;
    }
    envelope.state.previous=previous;envelope.sha256=digest(jsonBytes(envelope.state));previous=envelope.sha256;
  }
  need(changed>0,'WORKFLOW_REVIEW_MISSING');
  const destination=await openDossierStore(join(runDirectory,'rejected-review'));
  need((await destination.list()).length===0,'WORKFLOW_REJECTION_DESTINATION_CHANGED');
  let code;
  try{await destination.reopen(incoming);}catch(error){code=error.code;}
  need(code==='PORTABLE_CITATION_REPLAY_CHANGED','WORKFLOW_ALTERED_REVIEW_ACCEPTED');
  need((await destination.list()).length===0,'WORKFLOW_REJECTED_REVIEW_PUBLISHED');
  return {code,dossierCount:0};
}

export async function runCitationReviewWorkflow({operation,editionFile,editionSha256,runDirectory,
  playwrightModule,chromiumExecutable,targetDoi,sourceReference='Retained original Crossref metadata edition'}){
  need(typeof operation==='string'&&/^[A-Za-z0-9_-]{8,100}$/.test(operation),'WORKFLOW_OPERATION_REQUIRED');
  need(typeof editionSha256==='string'&&/^[a-f0-9]{64}$/.test(editionSha256),'WORKFLOW_SOURCE_DIGEST_REQUIRED');
  for(const value of [editionFile,runDirectory,playwrightModule,chromiumExecutable])
    need(typeof value==='string'&&isAbsolute(value)&&resolve(value)===value,'WORKFLOW_ABSOLUTE_PATH_REQUIRED');
  const raw=await readResearchHostFile(editionFile,MAX_SOURCE,{sha256:editionSha256}),envelope=parseJson(raw);
  if(envelope.provider==='crossref-document')validateCrossrefDocumentEdition(envelope);
  else validateCrossrefEdition(envelope);
  need(targetDoi===undefined||typeof targetDoi==='string'&&targetDoi.length<=512,'WORKFLOW_TARGET_INVALID');
  runDirectory=await privateDirectory(runDirectory);
  const binding={operation,editionSha256,editionBytes:raw.length,provider:envelope.provider,sourceReference,
    targetDoi:targetDoi??null};
  const bindingFile=join(runDirectory,'input.json'),savedBinding=await optionalJson(bindingFile);
  if(savedBinding)need(same(savedBinding,binding),'WORKFLOW_INPUT_CHANGED');
  else await writeJson(bindingFile,binding,{exclusive:true});
  const resultFile=join(runDirectory,'result.json'),existing=await optionalJson(resultFile);
  if(existing){
    need(existing.schema===SCHEMA&&existing.state==='COMPLETE'&&same(existing.binding,binding),'WORKFLOW_RESULT_CHANGED');
    for(const artifact of existing.artifacts){
      need(typeof artifact.file==='string'&&artifact.file&&!isAbsolute(artifact.file)&&
        !artifact.file.split(/[\\/]/).some(value=>value==='..'||value==='.'||!value),
        'WORKFLOW_ARTIFACT_PATH_INVALID');
      const checked=await identity(join(runDirectory,artifact.file));
      need(checked.bytes===artifact.bytes&&checked.sha256===artifact.sha256,'WORKFLOW_ARTIFACT_CHANGED');
    }
    return {...existing,recovered:true};
  }
  const workspace=join(runDirectory,'workspace'),store=await openDossierStore(workspace);
  const seed=await prepare({store,runDirectory,binding,raw,targetDoi});
  const connectionFile=join(runDirectory,'connection.json'),previousConnection=await optionalJson(connectionFile);
  if(previousConnection)need(previousConnection.directory===workspace,'WORKFLOW_CONNECTION_CHANGED');
  const port=previousConnection?Number(new URL(previousConnection.url).port):0;
  const app=await startDossierWorkspace({directory:workspace,port});
  let browser,selection,merchant;
  try{
    await writeJson(connectionFile,{schema:'stellar-forge.research-workspace-connection.v1',
      mode:'RESEARCH_DOSSIER_WORKSPACE',directory:workspace,url:app.url,workspaceId:app.workspaceId,instanceId:app.instanceId});
    const {runCitationReviewBrowser}=await import('./citation-review-browser.mjs');
    browser=await runCitationReviewBrowser({url:app.url,dossierId:seed.dossierId,noticeId:seed.noticeId,
      runDirectory,playwrightModule,chromiumExecutable});
    need(object(browser)&&typeof browser.reviewId==='string'&&Number.isSafeInteger(browser.originalRevision)&&
      Number.isSafeInteger(browser.reviewedRevision)&&Number.isSafeInteger(browser.currentRevision),
      'WORKFLOW_BROWSER_REVIEW_REQUIRED');
    const selectionFile=join(runDirectory,'completion-selection.json'),prior=await optionalJson(selectionFile);
    if(prior){need(prior.reviewId===browser.reviewId,'WORKFLOW_REVIEW_SELECTION_CHANGED');selection=prior;}
    else{
      selection={dossierId:seed.dossierId,noticeId:seed.noticeId,reviewId:browser.reviewId,
        originalRevision:browser.originalRevision,reviewedRevision:browser.reviewedRevision,currentRevision:browser.currentRevision};
      await writeJson(selectionFile,selection,{exclusive:true});
    }
    const detail=await store.citationUpdates(seed.dossierId,{noticeId:seed.noticeId,revision:selection.currentRevision});
    const review=detail.detail.reviews.find(value=>value.id===selection.reviewId);
    need(review&&review.originalRevision===selection.originalRevision&&review.revision===selection.reviewedRevision,
      'WORKFLOW_REVIEW_SELECTION_CHANGED');
    const before=(await store.getMetadata(seed.dossierId)).revision;
    const duplicate=await store.reviewCitationUpdate(seed.dossierId,review.request);
    need(duplicate.duplicate&&duplicate.review.id===review.id&&
      (await store.getMetadata(seed.dossierId)).revision===before,'WORKFLOW_REQUEST_RECOVERY_CHANGED');
    const {runCitationReviewMerchant}=await import('./citation-review-merchant.mjs');
    merchant=await runCitationReviewMerchant({url:app.url,workspaceDirectory:workspace,runDirectory,
      dossierId:seed.dossierId,noticeId:seed.noticeId,selection,reviewRequest:review.request});
    need(merchant?.reviewId===review.id&&merchant.originalRevision===selection.originalRevision&&
      merchant.reviewedRevision===selection.reviewedRevision&&merchant.currentRevision===selection.currentRevision,
      'WORKFLOW_MERCHANT_SELECTION_CHANGED');
    need((await store.getMetadata(seed.dossierId)).revision===before,'WORKFLOW_MERCHANT_REPLAY_CREATED_REVISION');
  }finally{await app.close();}
  const outputDirectory=await privateDirectory(join(runDirectory,'delivery'));
  await immutableBytes(join(outputDirectory,'original-source-edition.json'),raw);
  const artifacts=await reports({store,id:seed.dossierId,selection,directory:outputDirectory});
  artifacts.push({...await identity(join(outputDirectory,'original-source-edition.json')),kind:'source'});
  const jsonFile=join(outputDirectory,'complete.research.json'),gzipFile=jsonFile+'.gz';
  const jsonStore=await openDossierStore(join(runDirectory,'reopened-json'));
  await jsonStore.reopen(parseJson(await readBytes(jsonFile,MAX_PORTABLE)));
  const jsonReopen=await verifyReopened({original:store,received:jsonStore,id:seed.dossierId,
    selection,noticeId:seed.noticeId,rawSha256:editionSha256});
  const gzipStore=await openDossierStore(join(runDirectory,'reopened-gzip'));
  await gzipStore.reopenStream(await openPortableFile(gzipFile),{projection:'metadata'});
  const gzipReopen=await verifyReopened({original:store,received:gzipStore,id:seed.dossierId,
    selection,noticeId:seed.noticeId,rawSha256:editionSha256});
  const alteredReview=await rejectAlteredReview({portableFile:jsonFile,selection,runDirectory});
  const nativeOutputs=[
    ...(Array.isArray(browser.nativeOutputs)?browser.nativeOutputs:[]).map(output=>({output,kind:'browser'})),
    ...(Array.isArray(merchant.nativeOutputs)?merchant.nativeOutputs:[]).map(output=>({output,kind:'merchant'}))
  ];
  for(const {output,kind} of nativeOutputs){
    const candidate=typeof output==='string'?output:output.file??output.path??output.filename;
    need(typeof candidate==='string','WORKFLOW_NATIVE_ARTIFACT_INVALID');
    const file=isAbsolute(candidate)?candidate:join(runDirectory,candidate),name=relative(runDirectory,file);
    need(name&&!name.startsWith('..'+sep)&&!isAbsolute(name)&&
      !name.split(sep).some(value=>['connection.json','connection.private.json','retained-exports','citation-browser-profile','source-state','workspace',
        'reopened-json','reopened-gzip','rejected-review'].includes(value)),'WORKFLOW_PRIVATE_ARTIFACT_REFUSED');
    const checked=await identity(file);
    if(object(output))need((output.bytes===undefined||output.bytes===checked.bytes)&&
      (output.sha256===undefined||output.sha256===checked.sha256),'WORKFLOW_NATIVE_ARTIFACT_CHANGED');
    artifacts.push({...checked,kind});
  }
  const unique=new Map();
  for(const artifact of artifacts){
    const name=relative(runDirectory,artifact.file);
    need(!name.startsWith('..'+sep)&&!isAbsolute(name),'WORKFLOW_ARTIFACT_PATH_INVALID');
    const value={...artifact,file:name.split(sep).join('/')},old=unique.get(value.file);
    need(!old||old.sha256===value.sha256&&old.bytes===value.bytes,'WORKFLOW_ARTIFACT_CHANGED');unique.set(value.file,value);
  }
  const result={schema:SCHEMA,state:'COMPLETE',operation,binding,seed,selection,
    merchant:{workspaceId:merchant.workspaceId,exports:merchant.exports},jsonReopen,gzipReopen,
    alteredReview,artifacts:[...unique.values()],completedAt:new Date().toISOString()};
  await writeJson(resultFile,result,{exclusive:true});
  return result;
}

async function main(){
  const {values}=parseArgs({options:Object.fromEntries(
    ['operation','edition-file','sha256','run-directory','playwright-module','chromium','target-doi','source-reference']
      .map(value=>[value,{type:'string'}])),strict:true});
  const result=await runCitationReviewWorkflow({operation:values.operation,editionFile:values['edition-file'],
    editionSha256:values.sha256,runDirectory:values['run-directory'],playwrightModule:values['playwright-module'],
    chromiumExecutable:values.chromium,targetDoi:values['target-doi'],sourceReference:values['source-reference']});
  process.stdout.write(JSON.stringify(result,null,2)+'\n');
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))
  main().catch(error=>{process.stderr.write(JSON.stringify({error:error.code??'CITATION_WORKFLOW_FAILED'})+'\n');process.exitCode=1;});

// MIT. Review registered Crossref notices against the original saved dossier.
// Relationship direction: notice.DOI updates each update-to[].DOI.
// https://github.com/CrossRef/rest-api-doc/blob/master/api_format.md#update
import {digest,jsonBytes,need,object} from '../node/store.mjs';
import {normalizeDoi,dateLabel} from '../../sf30-seller-sdk/crossref/metadata.mjs';
import {validateCrossrefEdition} from './crossref.mjs';
import {validateCrossrefDocumentEdition} from './crossref-documents.mjs';

export const CITATION_REVIEW_SCHEMA='sf88-citation-update-review.v1';
export const CITATION_DECISIONS=Object.freeze(['retain','revise','exclude','follow-up']);
export const FINDING_DISPOSITIONS=Object.freeze(['unchanged','revised','citation-removed','follow-up']);
const clone=value=>structuredClone(value);
const array=value=>Array.isArray(value)?value:[];
const canonical=value=>Array.isArray(value)?value.map(canonical):object(value)?
  Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
export const citationDigest=value=>digest(jsonBytes(canonical(value)));
const doi=value=>{try{return normalizeDoi(value);}catch{return null;}};
const text=(value,code,max,empty=false)=>{
  need(typeof value==='string'&&value.length<=max&&(empty||value.trim().length>0),code);return value;
};
const hash=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
const occurrence=value=>typeof value==='string'&&/^o_[a-f0-9]{64}$/.test(value);
const finding=value=>typeof value==='string'&&/^f_[a-f0-9-]{36}$/.test(value);
const same=(left,right)=>citationDigest(left)===citationDigest(right);
const fields=(value,names)=>Object.fromEntries(names.map(key=>[key,value[key]]));
const SELECTION_FIELDS=['occurrenceId','editionId','questionId','key','selected','classification','note','updatedAt'];
const FINDING_FIELDS=['id','questionId','title','text','occurrenceIds','createdAt','updatedAt'];
function defined(value){return Object.fromEntries(Object.entries(value).filter(([,item])=>item!==undefined));}
const selectionSnapshot=value=>defined(fields(value,SELECTION_FIELDS));
const findingSnapshot=value=>defined(fields(value,FINDING_FIELDS));
function meaningfulRecord(work,relations){
  // Index/deposit time and citation counters do not change an editorial notice.
  // All original values and assertion ordering remain in the retained response.
  const value=Object.fromEntries(Object.entries(work).filter(([key])=>
    !['indexed','deposited','created','score','is-referenced-by-count','reference-count','references-count','update-to'].includes(key)));
  return {...value,'update-to':relations};
}
function registeredAssertions(relations){
  const unique=new Map();
  for(const relation of relations)unique.set(citationDigest(relation),clone(relation));
  return [...unique.entries()].sort(([left],[right])=>left<right?-1:left>right?1:0).map(([,value])=>value);
}
export function citationNoticeSnapshot(notice){
  return Object.fromEntries(['noticeId','noticeDoi','targetDoi','type','label','title','date',
    'noticeVersion','registeredUpdate','registeredUpdates','latestSource','noticeSources','versions']
    .map(key=>[key,clone(notice[key])]));
}
function brief(review){
  if(!review)return null;
  return fields(review,['id','requestId','actor','decision','reason','createdAt','originalRevision','revision','beforeFingerprint','afterFingerprint']);
}

/** Derive links from verified original envelopes, including notices acquired in another question. */
export function citationUpdateModel(state,projected){
  need(object(state)&&projected instanceof Map,'CITATION_DOSSIER_REQUIRED');
  const notices=new Map(),coverage=[],occurrences=new Map();
  for(const edition of state.editions){
    const projection=projected.get(edition.id);
    for(const row of projection?.items??[]){
      const occurrenceId='o_'+digest(Buffer.from(edition.id+'\n'+row.key));
      const selected=state.selections.find(item=>item.occurrenceId===occurrenceId);
      occurrences.set(occurrenceId,{occurrenceId,editionId:edition.id,questionId:edition.questionId,key:row.key,
        title:row.title,doi:doi(row.doi),retained:edition.mode==='retained',
        selected:selected?.selected??false,classification:selected?.classification??'unreviewed',
        note:selected?.note??'',...(selected?.updatedAt?{updatedAt:selected.updatedAt}:{})});
    }
    const raw=projection?.raw;
    const documentEdition=raw?.provider==='crossref-document'||(!raw&&edition.provider==='crossref-document');
    const isCrossref=documentEdition||raw?.provider==='crossref'||projection?.provider==='crossref'||
      edition.provider==='crossref'||edition.provider==='crossref-document';
    if(!isCrossref)continue;
    const observed={editionId:edition.id,questionId:edition.questionId,label:edition.label,createdAt:edition.createdAt,
      sourceSha256:edition.raw?.sha256??null,sourceKind:documentEdition?'retained-document':'http-capture',
      coverage:'UNAVAILABLE',updatesLookup:'NOT_RETAINED',
      requestedDois:[],updateRequestedDois:[],missingUpdates:[],issues:[]};
    coverage.push(observed);
    if(edition.mode!=='retained'){
      observed.issues.push('CROSSREF_REFERENCE_ONLY');continue;
    }
    try{documentEdition?validateCrossrefDocumentEdition(raw):validateCrossrefEdition(raw);}
    catch(error){observed.issues.push(error.code??'CROSSREF_ORIGINAL_CAPTURE_REQUIRED');continue;}
    Object.assign(observed,{coverage:raw.usage.coverage,updatesLookup:raw.usage.updatesLookup,
      requestedDois:clone(raw.usage.requestedDois),
      updateRequestedDois:clone(raw.usage.updateRequestedDois??(raw.usage.updatesLookup==='REQUESTED'?raw.usage.requestedDois:[])),
      missingUpdates:clone(raw.usage.missingUpdates??[]),
      issues:array(raw.warnings).map(value=>value.code)});
    for(let index=0;index<raw.results.length;index++){
      const result=raw.results[index],work=result.metadata?.crossref,noticeDoi=doi(work?.DOI);
      if(!noticeDoi)continue;
      const grouped=new Map();
      for(const relation of array(work['update-to'])){
        const targetDoi=doi(relation?.DOI);
        if(!targetDoi||typeof relation.type!=='string'||!relation.type.trim()){
          observed.issues.push('CROSSREF_UPDATE_RELATION_INVALID');continue;
        }
        const type=relation.type,noticeId='cu_'+citationDigest({noticeDoi,targetDoi,type});
        if(!grouped.has(noticeId))grouped.set(noticeId,{noticeId,targetDoi,type,relations:[]});
        grouped.get(noticeId).relations.push(relation);
      }
      for(const {noticeId,targetDoi,type,relations} of grouped.values()){
        // Publisher and Retraction Watch may both register this same notice.
        // Keep every distinct assertion; array order and duplicate rows do not
        // create a second impact or spuriously reopen a completed review.
        const registeredUpdates=registeredAssertions(relations),registeredUpdate=registeredUpdates[0];
        const recordSha256=citationDigest(work);
        const noticeVersion=citationDigest(meaningfulRecord(work,registeredUpdates));
        let notice=notices.get(noticeId);
        if(!notice){
          notice={noticeId,noticeDoi,targetDoi,type,noticeSources:[],versions:[]};
          notices.set(noticeId,notice);
        }
        const sourceOccurrenceId='o_'+digest(Buffer.from(edition.id+'\n'+index));
        const captures=documentEdition?[]:array(result.metadata.sourceOccurrences).map(item=>({
          captureSha256:item.captureSha256,sourceUrl:item.sourceUrl,retrievedAt:item.retrievedAt,
          role:item.role,requestedDois:clone(item.requestedDois)}));
        const documents=documentEdition?array(result.metadata.sourceDocuments).map(clone):[];
        const source={editionId:edition.id,editionLabel:edition.label,questionId:edition.questionId,
          sourceKind:documentEdition?'retained-document':'http-capture',
          occurrenceId:sourceOccurrenceId,key:String(index),sourceSha256:edition.raw.sha256,
          sourceBytes:edition.raw.bytes,recordSha256,noticeVersion,registeredUpdate,registeredUpdates,captures,documents};
        notice.noticeSources.push(source);
        if(!notice.versions.some(value=>value.noticeVersion===noticeVersion))
          notice.versions.push({noticeVersion,title:result.title,registeredUpdate,registeredUpdates,
            sourceSha256:edition.raw.sha256});
        // Dossier edition order selects the latest received observation. Prior
        // observations, including an absent relationship in a later response, remain retained.
        Object.assign(notice,{title:result.title,date:dateLabel(registeredUpdate.updated),
          label:registeredUpdate.label??type,noticeVersion,registeredUpdate,registeredUpdates,latestSource:source});
      }
    }
  }
  const citationOptions=[...occurrences.values()].map(value=>fields(value,
    ['occurrenceId','questionId','editionId','key','title','doi','retained']));
  const reviews=state.citationReviews??[];
  for(const notice of notices.values()){
    notice.evidence=[...occurrences.values()].filter(value=>value.doi===notice.targetDoi);
    const affected=new Set(notice.evidence.map(value=>value.occurrenceId));
    notice.findings=state.findings.filter(value=>value.occurrenceIds.some(id=>affected.has(id))).map(value=>({
      ...findingSnapshot(value),affectedOccurrenceIds:value.occurrenceIds.filter(id=>affected.has(id))}));
    const used=new Set(notice.findings.flatMap(value=>value.occurrenceIds));
    notice.evidence=notice.evidence.map(value=>({...value,usedByFinding:used.has(value.occurrenceId)}));
    notice.questionIds=[...new Set([...notice.evidence.map(value=>value.questionId),
      ...notice.findings.map(value=>value.questionId)])];
    notice.selectedEvidenceCount=notice.evidence.filter(value=>value.selected).length;
    notice.findingCount=notice.findings.length;
    notice.fingerprint=citationDigest({noticeId:notice.noticeId,noticeVersion:notice.noticeVersion,
      evidence:notice.evidence.filter(value=>value.selected||value.usedByFinding).map(value=>defined({
        occurrenceId:value.occurrenceId,editionId:value.editionId,questionId:value.questionId,
        title:value.title,selected:value.selected,classification:value.classification,note:value.note})),
      findings:notice.findings.map(value=>fields(value,['id','questionId','title','text','occurrenceIds']))});
    notice.reviews=reviews.filter(value=>value.noticeId===notice.noticeId).map(clone);
    const last=notice.reviews.at(-1);
    notice.lastReview=brief(last);
    notice.status=last?.afterFingerprint===notice.fingerprint?
      (last.decision==='follow-up'?'FOLLOW_UP':'REVIEWED'):last?'REVIEW_AGAIN':'PENDING';
    const questions=new Set(notice.findings.map(value=>value.questionId));
    notice.citationOptions=citationOptions.filter(value=>questions.has(value.questionId));
  }
  return {notices:[...notices.values()],coverage,occurrences};
}

export function citationUpdatePage(state,model,{noticeId,offset=0,limit=30,status='all'}={}){
  need(['all','pending','reviewed'].includes(status),'CITATION_REVIEW_FILTER_INVALID');
  need(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=100,
    'CITATION_REVIEW_PAGE_INVALID');
  const dossier={id:state.id,title:state.title,revision:state.revision};
  const counts={total:model.notices.length,pending:model.notices.filter(value=>['PENDING','REVIEW_AGAIN'].includes(value.status)).length,
    reviewed:model.notices.filter(value=>value.status==='REVIEWED').length,
    followUp:model.notices.filter(value=>value.status==='FOLLOW_UP').length};
  const base={schema:CITATION_REVIEW_SCHEMA,dossier,counts,coverage:clone(model.coverage)};
  if(noticeId!==undefined){
    const detail=model.notices.find(value=>value.noticeId===noticeId);need(detail,'CITATION_NOTICE_NOT_FOUND');
    return {...base,detail:clone(detail)};
  }
  const values=model.notices.filter(value=>status==='all'||(status==='reviewed'?value.status==='REVIEWED':value.status!=='REVIEWED'));
  need(offset<=values.length,'CITATION_REVIEW_PAGE_INVALID');
  const items=values.slice(offset,offset+limit).map(value=>({...fields(value,
    ['noticeId','noticeDoi','targetDoi','title','type','label','date','status','fingerprint',
      'selectedEvidenceCount','findingCount','questionIds','lastReview']),observationCount:value.noticeSources.length}));
  const nextOffset=offset+items.length<values.length?offset+items.length:null;
  return {...base,items,offset,limit,total:values.length,nextOffset};
}

export function citationReviewInput(input){
  need(object(input)&&Object.keys(input).every(key=>['requestId','noticeId','expectedFingerprint','expectedRevision',
    'actor','decision','reason','evidenceChanges','findingChanges','findingDispositions'].includes(key)),
    'CITATION_REVIEW_FIELDS_INVALID');
  need(typeof input.requestId==='string'&&/^[A-Za-z0-9_-]{8,100}$/.test(input.requestId),'CITATION_REVIEW_REQUEST_REQUIRED');
  need(typeof input.noticeId==='string'&&/^cu_[a-f0-9]{64}$/.test(input.noticeId),'CITATION_NOTICE_INVALID');
  need(hash(input.expectedFingerprint),'CITATION_REVIEW_FINGERPRINT_REQUIRED');
  need(Number.isSafeInteger(input.expectedRevision)&&input.expectedRevision>=1,'EXPECTED_REVISION_REQUIRED');
  need(CITATION_DECISIONS.includes(input.decision),'CITATION_REVIEW_DECISION_INVALID');
  const value={requestId:input.requestId,noticeId:input.noticeId,expectedFingerprint:input.expectedFingerprint,
    expectedRevision:input.expectedRevision,actor:text(input.actor,'CITATION_REVIEW_ACTOR_REQUIRED',200),
    decision:input.decision,reason:text(input.reason,'CITATION_REVIEW_REASON_REQUIRED',20000),
    evidenceChanges:[],findingChanges:[],findingDispositions:[]};
  for(const name of ['evidenceChanges','findingChanges','findingDispositions'])
    need(input[name]===undefined||Array.isArray(input[name])&&input[name].length<=10000,'CITATION_REVIEW_CHANGES_INVALID');
  value.evidenceChanges=array(input.evidenceChanges).map(item=>{
    need(object(item)&&Object.keys(item).every(key=>['occurrenceId','selected','classification','note'].includes(key))&&
      occurrence(item.occurrenceId)&&typeof item.selected==='boolean'&&
      ['supports','contradicts','background','unreviewed'].includes(item.classification),'CITATION_EVIDENCE_CHANGE_INVALID');
    return {occurrenceId:item.occurrenceId,selected:item.selected,classification:item.classification,
      note:text(item.note??'','CITATION_EVIDENCE_NOTE_INVALID',100000,true)};
  });
  value.findingChanges=array(input.findingChanges).map(item=>{
    need(object(item)&&Object.keys(item).every(key=>['id','title','text','occurrenceIds'].includes(key))&&finding(item.id)&&
      Array.isArray(item.occurrenceIds)&&item.occurrenceIds.every(occurrence)&&
      new Set(item.occurrenceIds).size===item.occurrenceIds.length,'CITATION_FINDING_CHANGE_INVALID');
    return {id:item.id,title:text(item.title,'FINDING_TITLE_REQUIRED',240),
      text:text(item.text,'FINDING_TEXT_REQUIRED',100000),occurrenceIds:[...item.occurrenceIds]};
  });
  value.findingDispositions=array(input.findingDispositions).map(item=>{
    need(object(item)&&Object.keys(item).every(key=>['findingId','disposition','reason'].includes(key))&&
      finding(item.findingId)&&FINDING_DISPOSITIONS.includes(item.disposition),'CITATION_FINDING_DISPOSITION_INVALID');
    return {findingId:item.findingId,disposition:item.disposition,
      reason:text(item.reason,'CITATION_FINDING_REASON_REQUIRED',20000)};
  });
  for(const [name,key]of [['evidenceChanges','occurrenceId'],['findingChanges','id'],['findingDispositions','findingId']])
    need(new Set(value[name].map(item=>item[key])).size===value[name].length,'CITATION_REVIEW_DUPLICATE_CHANGE');
  return value;
}

/** Apply exactly the operator's source/finding edits to one original state clone. */
export function applyCitationReview(state,model,input,createdAt){
  const notice=model.notices.find(value=>value.noticeId===input.noticeId);need(notice,'CITATION_NOTICE_NOT_FOUND');
  need(notice.fingerprint===input.expectedFingerprint,'CITATION_REVIEW_CHANGED');
  const evidence=new Map(notice.evidence.map(value=>[value.occurrenceId,value]));
  const affectedFindings=new Map(notice.findings.map(value=>[value.id,value]));
  need(input.findingDispositions.length===affectedFindings.size&&
    input.findingDispositions.every(value=>affectedFindings.has(value.findingId)),'CITATION_FINDING_DISPOSITION_REQUIRED');
  const changes={evidence:[],findings:[]};
  for(const change of input.evidenceChanges){
    const source=evidence.get(change.occurrenceId);need(source,'CITATION_EVIDENCE_OUTSIDE_NOTICE');
    let saved=state.selections.find(value=>value.occurrenceId===change.occurrenceId);
    const before=saved?selectionSnapshot(saved):null;
    const old={selected:saved?.selected??false,classification:saved?.classification??'unreviewed',note:saved?.note??''};
    if(same(old,fields(change,['selected','classification','note'])))continue;
    if(!saved){
      saved=fields(source,['occurrenceId','editionId','questionId','key']);
      state.selections.push(saved);
    }
    Object.assign(saved,change,{updatedAt:createdAt});
    changes.evidence.push({occurrenceId:change.occurrenceId,before,after:selectionSnapshot(saved)});
  }
  for(const change of input.findingChanges){
    need(affectedFindings.has(change.id),'CITATION_FINDING_OUTSIDE_NOTICE');
    const saved=state.findings.find(value=>value.id===change.id),before=findingSnapshot(saved);
    for(const key of change.occurrenceIds){
      const citation=model.occurrences.get(key);
      need(citation?.questionId===saved.questionId||(!citation&&saved.occurrenceIds.includes(key)),
        'FINDING_SOURCE_QUESTION_MISMATCH');
    }
    if(same(fields(saved,['id','title','text','occurrenceIds']),change))continue;
    Object.assign(saved,change,{updatedAt:createdAt});
    changes.findings.push({findingId:change.id,before,after:findingSnapshot(saved)});
  }
  for(const disposition of input.findingDispositions){
    const updated=state.findings.find(value=>value.id===disposition.findingId);
    const changed=changes.findings.some(value=>value.findingId===disposition.findingId);
    if(disposition.disposition==='unchanged')need(!changed,'CITATION_FINDING_DISPOSITION_MISMATCH');
    if(disposition.disposition==='revised')need(changed,'CITATION_FINDING_DISPOSITION_MISMATCH');
    if(disposition.disposition==='citation-removed')need(changed&&updated.occurrenceIds.every(id=>!evidence.has(id)),
      'CITATION_FINDING_DISPOSITION_MISMATCH');
  }
  return {notice,changes};
}

/** Record the complete review by applying its request once to the actual previous state. */
export function recordCitationReview(state,projected,input,createdAt){
  const request=citationReviewInput(input);
  need(state.revision===request.expectedRevision,'REVISION_CONFLICT');
  need(typeof createdAt==='string'&&Number.isFinite(Date.parse(createdAt)),'CITATION_REVIEW_TIME_INVALID');
  need(!(state.citationReviews??[]).some(value=>value.requestId===request.requestId),
    'CITATION_REVIEW_REQUEST_ALREADY_RECORDED');
  const originalRevisionSha256=digest(jsonBytes(state));
  const model=citationUpdateModel(state,projected),applied=applyCitationReview(state,model,request,createdAt);
  const after=citationUpdateModel(state,projected).notices.find(value=>value.noticeId===request.noticeId);
  const payload={schema:CITATION_REVIEW_SCHEMA,
    id:'cur_'+citationDigest({dossierId:state.id,requestId:request.requestId}),dossierId:state.id,
    requestId:request.requestId,requestSha256:citationDigest(request),request:clone(request),noticeId:request.noticeId,
    actor:request.actor,decision:request.decision,reason:request.reason,createdAt,
    originalRevision:state.revision,originalRevisionSha256,revision:state.revision+1,
    beforeFingerprint:applied.notice.fingerprint,afterFingerprint:after.fingerprint,
    notice:citationNoticeSnapshot(applied.notice),changes:applied.changes,
    findingDispositions:clone(request.findingDispositions)};
  const review={...payload,sha256:citationDigest(payload)};
  state.citationReviews=[...(state.citationReviews??[]),review];
  return review;
}

/** Immutable review entries travel with every original JSON/streamed portable revision. */
export function validateCitationReviewState(state,editions){
  need(state.citationReviews===undefined||Array.isArray(state.citationReviews),'PORTABLE_CITATION_REVIEWS_INVALID');
  const ids=new Set(),requests=new Set();
  for(const review of state.citationReviews??[]){
    need(object(review)&&review.schema===CITATION_REVIEW_SCHEMA&&
      review.id==='cur_'+citationDigest({dossierId:state.id,requestId:review.requestId})&&
      review.dossierId===state.id&&Number.isSafeInteger(review.originalRevision)&&review.originalRevision>=1&&
      review.revision===review.originalRevision+1&&review.revision<=state.revision&&
      hash(review.originalRevisionSha256)&&hash(review.beforeFingerprint)&&hash(review.afterFingerprint)&&
      typeof review.createdAt==='string'&&Number.isFinite(Date.parse(review.createdAt)),
      'PORTABLE_CITATION_REVIEW_INVALID');
    need(!ids.has(review.id)&&!requests.has(review.requestId),'PORTABLE_CITATION_REVIEW_DUPLICATE');
    ids.add(review.id);requests.add(review.requestId);
    const request=citationReviewInput(review.request);
    need(same(request,review.request)&&citationDigest(request)===review.requestSha256&&
      review.requestId===request.requestId&&review.noticeId===request.noticeId&&
      review.originalRevision===request.expectedRevision&&review.beforeFingerprint===request.expectedFingerprint&&
      review.actor===request.actor&&review.reason===request.reason&&review.decision===request.decision,
      'PORTABLE_CITATION_REQUEST_CHANGED');
    const {sha256,...payload}=review;need(sha256===citationDigest(payload),'PORTABLE_CITATION_REVIEW_CHANGED');
    const source=review.notice?.latestSource,edition=editions.get(source?.editionId);
    need(edition?.mode==='retained'&&edition.raw.sha256===source.sourceSha256&&edition.raw.bytes===source.sourceBytes&&
      occurrence(source.occurrenceId)&&source.occurrenceId==='o_'+digest(Buffer.from(edition.id+'\n'+source.key))&&
      review.notice.noticeId===review.noticeId&&hash(review.notice.noticeVersion)&&
      ['http-capture','retained-document'].includes(source.sourceKind)&&
      Array.isArray(source.captures)&&source.captures.every(value=>hash(value.captureSha256)&&
        typeof value.sourceUrl==='string'&&value.sourceUrl.startsWith('https://api.crossref.org/'))&&
      Array.isArray(source.documents)&&source.documents.every(value=>
        typeof value.documentId==='string'&&value.documentId.length>0&&hash(value.documentSha256)&&
        hash(value.bodySha256)&&Number.isSafeInteger(value.bodyBytes)&&value.bodyBytes>0&&
        typeof value.sourceUrl==='string'&&value.sourceUrl.startsWith('https://api.crossref.org/'))&&
      (source.sourceKind==='retained-document'?source.documents.length>0&&source.captures.length===0:
        source.captures.length>0&&source.documents.length===0),
      'PORTABLE_CITATION_NOTICE_BINDING_INVALID');
    need(object(review.changes)&&Array.isArray(review.changes.evidence)&&Array.isArray(review.changes.findings)&&
      Array.isArray(review.findingDispositions)&&same(review.findingDispositions,request.findingDispositions),
      'PORTABLE_CITATION_CHANGES_INVALID');
  }
}
export function validateCitationReviewTransition(previous,state,projected){
  const old=previous?.citationReviews??[],current=state.citationReviews??[];
  need(current.length>=old.length&&old.every((value,index)=>same(value,current[index])),
    'PORTABLE_CITATION_HISTORY_CHANGED');
  const added=current.slice(old.length);
  need(added.length<=1&&added.every(value=>value.revision===state.revision&&
    value.originalRevision===previous?.revision&&value.originalRevisionSha256===state.previous),
    'PORTABLE_CITATION_HISTORY_INVALID');
  if(!added.length)return;
  need(previous&&projected instanceof Map,'PORTABLE_CITATION_SOURCE_REQUIRED');
  need(state.revision===previous.revision+1&&state.previous===digest(jsonBytes(previous)),
    'PORTABLE_CITATION_HISTORY_INVALID');
  // Reuse the exact operation that saved the review. This binds the notice and
  // every assertion/capture/occurrence to the original retained edition, and
  // verifies the saved text, citations and evidence changes against its request.
  const expected=clone(previous),review=added[0];
  const replayed=recordCitationReview(expected,projected,review.request,review.createdAt);
  need(same(replayed,review),'PORTABLE_CITATION_REPLAY_CHANGED');
  Object.assign(expected,{revision:state.revision,previous:state.previous,
    updatedAt:state.updatedAt,change:state.change});
  need(same(expected,state),'PORTABLE_CITATION_STATE_CHANGED');
}

#!/usr/bin/env node
// MIT — The original buyer acquires; this command organizes its returned research.
import { parseArgs } from 'node:util';
import { resolve } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { readBytes, parseJson, writeBytes, need } from '../node/store.mjs';
import { openDossierStore } from './dossier.mjs';
import {createSourceBundleFromDirectory,inspectSourceBundle,SOURCE_BUNDLE_LIMIT} from './source-bundles.mjs';
import { openPortableFile, writePortableFile } from './portable.mjs';
import { receiveOpenAlexEdition } from './openalex.mjs';
import { openSavedOpenAlexWorkspace } from './openalex-workspace.mjs';

const usage = 'Research dossiers\n\n' +
  '  remote COMMAND --connection-file FILE --directory ORIGINAL_STORE [OPTIONS]\n' +
  '  bundle-create --manifest FILE --source-directory DIR --out FILE\n' +
  '  bundle-preview --file SOURCE_BUNDLE_JSON\n' +
  '  import-bundle --store DIR --id ID --question ID --file SOURCE_BUNDLE_JSON --revision N [--sha256 HASH] [--projection full|metadata]\n' +
  '  create --store DIR --title TEXT [--description TEXT]\n' +
  '  list|get --store DIR [--id ID] [--revision N]\n' +
  '  question --store DIR --id ID --text TEXT --revision N\n' +
  '  receive --store DIR --id ID --question ID --file JSON --provider openalex|research --label TEXT --revision N\n' +
  '  attach --store DIR --id ID --question ID --file REFERENCE_JSON --provider valyu --label TEXT --revision N [--edition-adapter MODULE]\n' +
  '  import-buyer --store DIR --id ID --question ID --buyer-state DIR --runtime DIR --intent ID --provider openalex|research --label TEXT --revision N\n' +
  '  import-openalex --store DIR --id ID --question ID --openalex-workspace DIR --edition ID --revision N [--openalex-module MODULE] [--label TEXT]\n' +
  '  note --store DIR --id ID --source ID --selected true|false --note TEXT --classification supports|contradicts|background|unreviewed --revision N\n' +
  '  finding --store DIR --id ID --file FINDING_JSON --revision N\n' +
  '  citation-updates --store DIR --id ID [--revision N] [--notice ID] [--offset N] [--limit N]\n' +
  '  citation-review --store DIR --id ID --file REVIEW_REQUEST_JSON\n' +
  '  compare --store DIR --id ID --before N --after N\n' +
  '  export --store DIR --id ID --format json|json.gz|md|html --out FILE\n' +
  '  reopen --store DIR --file PORTABLE_JSON_OR_GZIP [--projection full|metadata]\n';

export async function main(argv = process.argv.slice(2)) {
  const command = argv[0];
  if(command==='remote')return (await import('./workspace-cli.mjs')).main(argv.slice(1));
  if (!command || ['help', '--help', '-h'].includes(command)) { process.stdout.write(usage); return; }
  const keys = ['store', 'id', 'title', 'description', 'text', 'revision', 'question', 'file',
    'provider', 'label', 'source-reference', 'source', 'selected', 'note', 'classification',
    'before', 'after', 'format', 'out', 'edition-adapter', 'buyer-state', 'runtime', 'intent',
    'openalex-workspace', 'openalex-module', 'edition', 'projection', 'manifest', 'source-directory', 'sha256',
    'notice','offset','limit','status'];
  const { values } = parseArgs({ args: argv.slice(1), options: Object.fromEntries(keys.map(key => [key, { type: 'string' }])), strict: true });
  if(command==='bundle-create'){
    need(values.manifest&&values['source-directory']&&values.out,'SOURCE_BUNDLE_INPUTS_REQUIRED');
    const prepared=await createSourceBundleFromDirectory({manifestFile:resolve(values.manifest),
      directory:resolve(values['source-directory'])});
    await writeBytes(resolve(values.out),prepared.bytes,{exclusive:true});
    process.stdout.write(JSON.stringify({file:resolve(values.out),...prepared.preview},null,2)+'\n');return;
  }
  if(command==='bundle-preview'){
    need(values.file,'SOURCE_BUNDLE_FILE_REQUIRED');
    const prepared=inspectSourceBundle(await readBytes(resolve(values.file),SOURCE_BUNDLE_LIMIT));
    process.stdout.write(JSON.stringify(prepared.preview,null,2)+'\n');return;
  }
  need(values.store, 'STORE_REQUIRED');
  let providers = {};
  if (values['edition-adapter']) {
    const installed = await import(pathToFileURL(resolve(values['edition-adapter'])).href);
    providers = installed.providers;
    need(providers && typeof providers === 'object', 'EDITION_PROVIDERS_INVALID');
  }
  const store = await openDossierStore(resolve(values.store), { providers });
  const revision = values.revision === undefined ? undefined : Number(values.revision);
  const input = async () => parseJson(await readBytes(resolve(values.file), command==='citation-review'?16*1024*1024:256*1024*1024));
  let result;
  switch (command) {
    case 'create': result = await store.create({ title: values.title, description: values.description ?? '' }); break;
    case 'list': result = await store.list(); break;
    case 'get': result = await store.get(values.id, { revision }); break;
    case 'question': result = await store.addQuestion(values.id, { text: values.text, expectedRevision: revision }); break;
    case 'receive':
      result = await store.receive(values.id, { questionId: values.question, label: values.label,
        provider: values.provider ?? 'research', rawBytes: await readBytes(resolve(values.file), 64 * 1024 * 1024),
        sourceReference: values['source-reference'] ?? '', expectedRevision: revision }); break;
    case 'import-bundle':
      need(values.file,'SOURCE_BUNDLE_FILE_REQUIRED');
      result=await store.receiveSourceBundle(values.id,{questionId:values.question,
