  need(source&&['request','readCapture','snapshot'].every(key=>typeof source[key]==='function'),'CROSSREF_SOURCE_REQUIRED');
  need(object(identity)&&typeof identity.account==='string'&&['public','polite'].includes(identity.mode)&&
