 root.addEventListener('click',event=>{
  const button=event.target.closest('[data-ct]');if(!button||button.disabled)return;
  const name=button.dataset.ct;
  action(async()=>{
   if(name==='retained-analyze'){if(local.retainedCurrent)return openAnalysis('retained',local.retainedCurrent.edition.id);return;}
   if(name==='analyze'){if(local.current?.operation.editionSha256)return openAnalysis('operations',local.current.plan.id);return;}
   if(name.startsWith('analysis-')){
    if(!local.analysisTarget)return;
    if(name==='analysis-clear')return loadAnalysis(true,{criteria:{},offset:0});
    if(name==='analysis-prev'||name==='analysis-next')return loadAnalysis(false,{offset:Math.max(0,local.analysisOffset+(name==='analysis-next'?50:-50))});
    if(name==='analysis-record'){
     const target=local.analysisTarget,value=await api(endpoint('/'+target.kind+'/'+encodeURIComponent(target.id)+'/record')+'?index='+encodeURIComponent(button.dataset.index));
     $('analysis-record-body').textContent=sourceText(value);$('analysis-record').hidden=false;$('analysis-record').open=true;return;
    }
    if(name.startsWith('analysis-export-')){
     const format=name.slice('analysis-export-'.length);
     return download(analysisPath('/'+format)+'?'+appliedQuery(),'clinicaltrials-cohort.'+format);
    }
   }
   if(name==='refresh')return refresh();
   if(name==='more-inputs')return loadInputs(true);
   if(name==='input-packet'){const selected=selectedInput();if(!selected)return;
    return download(endpoint('/inputs/'+selected.input.sourceId+'/packet'),'clinicaltrials-workspace-'+selected.input.packetSha256.slice(0,12)+'.zip');}
   if(name==='import-packet'){
    const file=$('packet-file').files?.[0];if(!file){notify('Choose the original ClinicalTrials source ZIP.');return;}
    if(!file.size||file.size>128*1024*1024){notify('Choose an original source packet up to 128 MiB.');return;}
    const sha256=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');
    const generation=local.generation;
    notify('Receiving and reading the original source packet…');
    const received=await api(endpoint('/inputs')+'?sha256='+sha256+'&bytes='+file.size,{method:'POST',file});
    if(generation!==local.generation)return;
    await loadInputs();if(received.captures.length)$('source-select').value=received.sourceId+':'+received.captures[0].id;
    renderInputs();notify('Original source packet retained with '+received.captures.length+' captured cohort(s).');return;
   }
   if(name==='more')return loadList(true);
   if(name==='retained-open'){
    const id=$('retained-select').value;if(!id){notify('Select the original retained edition.');return;}
    local.retainedOffset=0;$('retained-record').hidden=true;$('retained-comparison').hidden=true;return openRetained(id);
   }
   if(name.startsWith('retained-')){
    const selected=local.retainedCurrent;if(!selected)return;
    if(name==='retained-prev'||name==='retained-next'){local.retainedOffset=Math.max(0,local.retainedOffset+(name==='retained-next'?50:-50));return openRetained(selected.edition.id);}
    const path=endpoint('/retained/'+encodeURIComponent(selected.edition.id));
    if(name==='retained-download')return download(path+'/edition',selected.edition.id+'.clinicaltrials.json');
    if(name==='retained-packet')return download(path+'/packet','clinicaltrials-workspace.zip');
    if(name==='retained-record'){
     const value=await api(path+'/record?index='+encodeURIComponent(button.dataset.index));
     $('retained-record-body').textContent=sourceText(value);$('retained-record').hidden=false;$('retained-record').open=true;return;
    }
    if(name==='retained-compare'){
     const before=$('retained-before').value;if(!before){notify('Select an earlier original edition.');return;}
     const value=await api(endpoint('/retained/compare')+'?before='+encodeURIComponent(before)+'&after='+encodeURIComponent(selected.edition.id));
     $('retained-comparison').textContent=JSON.stringify(value,null,2);$('retained-comparison').hidden=false;return;
    }
   }
   if(name==='open'){local.current={plan:{id:button.dataset.id}};local.offset=0;$('record').hidden=true;$('comparison').hidden=true;return loadCurrent();}
   if(!local.current)return;
   if(name==='previous'||name==='next'){local.offset=Math.max(0,local.offset+(name==='next'?50:-50));return loadCurrent();}
   if(name==='start'||name==='stop'){
    local.current=await api(operation('/'+name),{method:'POST',body:name==='stop'?{}:{expectedPlanSha256:local.current.plan.sha256}});
    await loadCurrent();await loadList();return;
   }
   if(name==='receive'){
    const result=await api(operation('/receive'),{method:'POST',body:{expectedRevision:getDossier().revision,
     expectedPlanSha256:local.current.plan.sha256,expectedEditionSha256:local.current.operation.editionSha256}});
    await onReceived(result.dossier);await loadCurrent();await loadList();await loadRetained();notify('Original registry edition retained at dossier revision '+result.receipt.revision+'.');return;
   }
   if(name==='download'){
    const response=await api(operation('/edition'),{download:true}),url=URL.createObjectURL(await response.blob()),link=document.createElement('a');
    link.href=url;link.download=local.current.plan.id+'.clinicaltrials.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);return;
   }
   if(name==='record'){
    const value=await api(operation('/record')+'?index='+encodeURIComponent(button.dataset.index));
    $('record-body').textContent=sourceText(value);$('record').hidden=false;$('record').open=true;return;
   }
   if(name==='compare'){
    if(!$('compare-with').value){notify('Select the original prior acquisition.');return;}
    const value=await api(operation('/compare')+'?before='+encodeURIComponent($('compare-with').value));
    $('comparison-body').textContent=JSON.stringify(value,null,2);$('comparison').hidden=false;
   }
  });
 });
 window.addEventListener('beforeunload',stopPoll);
 return {
  configure(value){local.configured=value?.configured===true;tab.hidden=!local.configured&&!local.retained.length;
   $('form').hidden=!local.configured;$('source-status').textContent=local.configured?'The original packet reader is available. Source acquisition and merchant operation stay in the existing ClinicalTrials console.':'Original received registry editions remain readable.';
  },
  setDossier(view){
   if(view?.id!==local.dossierId){stopPoll();local.generation++;local.dossierId=view?.id??null;local.items=[];local.current=null;local.next=null;local.offset=0;local.retained=[];local.retainedCurrent=null;local.retainedOffset=0;local.inputs=[];local.inputsNext=null;local.analysisTarget=null;local.analysis=null;local.analysisFacets=null;local.analysisCriteria={};local.analysisOffset=0;
    try{local.pending=JSON.parse(sessionStorage.getItem(key())||'null');}catch{local.pending=null;}
    renderList();renderCurrent();renderRetained();renderInputs();renderAnalysis();
   }
   questions();local.retained=array(view?.editions).filter(row=>row.provider==='clinicaltrials-gov'&&row.mode==='retained');renderRetained();tab.hidden=!local.configured&&!local.retained.length;
  },
  show(visible){const changed=visible!==local.shown;local.shown=visible;if(!visible)stopPoll();else if(changed)refresh().catch(error=>notify(error.code||error.message,'error'));else schedule();},
  updateBusy(){for(const element of $('form').querySelectorAll('input,textarea,select,button'))element.disabled=isBusy()||!local.configured||!getDossier()?.questions?.length;renderCurrent();renderRetained();renderAnalysis();$('import-packet').disabled=isBusy();$('packet-file').disabled=isBusy();renderInputs();}
 };
}

// MIT. Crossref review controls use the original research workspace's session and dossier state.
export function createCrossrefPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  const local={configured:false,identity:null,dossierId:null,revision:null,shown:false,current:null,items:[],
    next:null,page:0,poll:null,loading:false,loadVersion:0,pending:null};
  root.innerHTML=`
    <div class="view-heading"><div><h2>DOI metadata</h2><p class="muted">Review publication metadata and registered updates for the evidence in a saved question.</p></div><button type="button" id="crossref-refresh">Refresh operations</button></div>
    <p id="crossref-account" class="muted small"></p>
    <form id="crossref-plan-form" class="crossref-form">
      <label>Research question<select id="crossref-question" required></select></label>
      <label>Edition label<input id="crossref-label" maxlength="200" value="Crossref DOI enrichment" required></label>
      <div class="crossref-options">
        <label><input type="checkbox" id="crossref-selected" checked>Selected evidence only</label>
        <label><input type="checkbox" id="crossref-updates" checked>Include registered updates</label>
        <label><input type="checkbox" id="crossref-fresh">Refresh provider responses</label>
      </div>
      <p class="muted small">The review records the exact DOI scope. Existing response captures are reused unless you request a refresh. Acquisition progress remains saved when this window closes.</p>
      <div class="crossref-form-footer"><p id="crossref-scope" class="muted small"></p><button type="submit" class="primary" id="crossref-prepare">Review acquisition</button></div>
      <p class="form-error" hidden></p>
    </form>
    <div class="crossref-layout">
      <section class="crossref-history" aria-label="Saved Crossref operations"><h3>Saved operations</h3><div id="crossref-operation-list"></div><button type="button" id="crossref-more" hidden>More operations</button></section>
      <section class="crossref-review" aria-label="Crossref operation review">
        <p id="crossref-empty" class="muted">Choose a saved operation or review a new acquisition.</p>
        <div id="crossref-review-content" hidden>
          <div class="crossref-review-heading"><div><h3 id="crossref-plan-title"></h3><p id="crossref-plan-state" role="status"></p></div><span class="tag" id="crossref-coverage"></span></div>
          <p id="crossref-plan-question"></p><p id="crossref-plan-meta" class="muted small"></p>
          <details class="original-record"><summary>Reviewed DOI scope</summary><pre id="crossref-dois"></pre></details>
          <div id="crossref-progress" class="provider-outcome" role="status"></div>
          <p id="crossref-problem" class="form-error" role="alert" hidden></p>
          <div class="button-row crossref-actions">
            <button type="button" class="primary" id="crossref-start">Acquire metadata</button>
            <button type="button" id="crossref-stop" hidden>Stop acquisition</button>
            <button type="button" class="primary" id="crossref-receive" hidden>Retain reviewed edition</button>
            <button type="button" id="crossref-download" hidden>Download original edition</button>
          </div>
          <div id="crossref-result" hidden>
            <h3>Received metadata</h3><p id="crossref-result-summary" class="muted small"></p>
            <div class="table-wrap"><table><thead><tr><th>Publication</th><th>Publication dates</th><th>Review</th></tr></thead><tbody id="crossref-records"></tbody></table></div>
            <div class="pagination"><button type="button" id="crossref-prev" class="quiet compact">Previous</button><span id="crossref-page"></span><button type="button" id="crossref-next" class="quiet compact">Next</button></div>
            <section id="crossref-record-detail" class="crossref-record-detail" hidden></section>
            <details class="original-record"><summary>Acquisition coverage and provider responses</summary><pre id="crossref-usage"></pre></details>
          </div>
        </div>
      </section>
    </div>`;
  const $=id=>root.querySelector('#'+id),nodes={};
  for(const element of root.querySelectorAll('[id]'))nodes[element.id]=element;
  const el=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(className)node.className=className;return node;};
  const array=value=>Array.isArray(value)?value:[];
  const stringify=value=>JSON.stringify(value,null,2);
  const endpoint=(suffix='',id=local.dossierId)=>'/api/dossiers/'+encodeURIComponent(id)+'/crossref'+suffix;
  const operationPath=(suffix='',current=local.current)=>endpoint('/operations/'+current.plan.id+suffix,current.plan.request.dossierId);
  const friendly=code=>String(code||'Operation failed').toLowerCase().replaceAll('_',' ');
  const date=value=>value?new Date(value).toLocaleString():'';
  const dateParts=value=>array(value?.['date-parts']).map(parts=>parts.join('-')).join('; ')||value?.['date-time']||'Not supplied';
  function stopPoll(){if(local.poll!==null)clearTimeout(local.poll);local.poll=null;}
  function schedule(){
    stopPoll();
    if(!local.shown||!local.current?.running)return;
    local.poll=setTimeout(()=>loadCurrent().catch(error=>problem(error.message)),1500);
  }
  function problem(message){$('crossref-problem').textContent=message;$('crossref-problem').hidden=!message;}
  function withAction(work,form=null){
    return task(async()=>{try{await work();}catch(error){
      if(error.code==='REVISION_CONFLICT'&&local.current)await loadCurrent().catch(()=>{});
      throw error;
    }finally{renderCurrent();renderScope();}},form);
  }
  function pendingKey(){return 'crossref-prepared-request:'+location.origin+':'+local.dossierId;}
  function restorePending(){try{local.pending=JSON.parse(sessionStorage.getItem(pendingKey())||'null');}catch{local.pending=null;}}
  function savePending(value){local.pending=value;try{if(value)sessionStorage.setItem(pendingKey(),JSON.stringify(value));else sessionStorage.removeItem(pendingKey());}catch{}}
  function scope(){
    const view=getDossier(),questionId=$('crossref-question').value,selectedOnly=$('crossref-selected').checked;
    return array(view?.sources).filter(source=>source.doi&&(!selectedOnly||source.selected)&&
      array(source.citations).some(citation=>citation.questionId===questionId));
  }
  function renderScope(){
    const count=new Set(scope().map(source=>String(source.doi).toLowerCase())).size;
    $('crossref-scope').textContent=count+' DOI source'+(count===1?'':'s')+' in the current question selection.';
    $('crossref-prepare').disabled=!local.configured||count===0||isBusy();
  }
  function renderQuestions(){
    const view=getDossier(),previous=$('crossref-question').value;
    $('crossref-question').replaceChildren(...array(view?.questions).map(question=>{const option=el('option',question.text);option.value=question.id;return option;}));
    if(array(view?.questions).some(question=>question.id===previous))$('crossref-question').value=previous;
    renderScope();
  }
  function renderList(){
    $('crossref-operation-list').replaceChildren(...local.items.map(item=>{
      const button=el('button',undefined,'crossref-operation'+(item.plan.id===local.current?.plan.id?' active':''));
      button.type='button';button.append(el('strong',item.plan.request.label),el('span',item.operation.phase+' · '+item.plan.payload.dois.length+' DOIs'),
        el('span',date(item.plan.preparedAt)));
      button.addEventListener('click',()=>withAction(async()=>{local.current=item;local.page=0;await loadCurrent();renderList();}));
      return button;
    }));
    if(!local.items.length)$('crossref-operation-list').append(el('p','Prepared scopes and results appear here.','muted small'));
    $('crossref-more').hidden=!local.next;
  }
  async function loadList({more=false}={}){
    const id=local.dossierId,version=local.loadVersion;if(!id||!local.configured)return;
    const data=await api(endpoint('/operations?limit=30'+(more&&local.next?'&after='+encodeURIComponent(local.next):''),id));
    if(version!==local.loadVersion||id!==local.dossierId)return;
    local.items=more?[...local.items,...data.items]:data.items;local.next=data.next;
    renderList();
  }
  async function loadCurrent(){
    if(!local.current||local.loading)return;
    const id=local.current.plan.id,dossierId=local.dossierId,version=local.loadVersion;local.loading=true;
    try{
      const value=await api(operationPath());
      if(version!==local.loadVersion||dossierId!==local.dossierId||id!==local.current?.plan.id)return;
      local.current=value;
      const index=local.items.findIndex(item=>item.plan.id===id);
      if(index>=0)local.items[index]={plan:value.plan,operation:value.operation};else local.items.unshift({plan:value.plan,operation:value.operation});
      renderCurrent();renderList();
    }finally{local.loading=false;schedule();}
  }
  async function refresh(){
    if(!local.configured||!local.dossierId)return;
    await loadList();
    if(local.current)await loadCurrent();
  }
  function fieldComparison(doi){
    const comparison=local.current?.review?.comparison;
    if(!comparison)return {label:'Retained record',fields:[]};
    const changed=array(comparison.changed).find(row=>row.doi===doi);
    if(changed)return {label:changed.fields.length+' changed field'+(changed.fields.length===1?'':'s'),fields:changed.fields};
    if(array(comparison.added).some(row=>row.doi===doi))return {label:'First Crossref metadata',fields:[]};
    return {label:'No saved Crossref field changes',fields:[]};
  }
  function displayRecord(record){
    const target=$('crossref-record-detail');target.hidden=false;target.replaceChildren(el('h3',record.title));
    const link=el('a',record.doi);link.href='https://doi.org/'+encodeURIComponent(record.doi);link.target='_blank';link.rel='noopener noreferrer';target.append(link);
    target.append(el('p',array(record.authors).join('; '),'muted small'));
    const table=el('table'),body=el('tbody');
    for(const [label,value] of Object.entries(record.dates||{})){const row=el('tr');row.append(el('th',label),el('td',dateParts(value)));body.append(row);}
    table.append(body);target.append(table);
    const comparison=fieldComparison(record.doi);
    target.append(el('h3',comparison.label));
    for(const field of comparison.fields){
      const details=el('details',undefined,'original-record');details.append(el('summary',field.field??field.key??'Changed field'));
      const pre=el('pre',stringify(field));details.append(pre);target.append(details);
    }
    for(const [title,value] of [['Funders',record.funders],['Licences',record.licenses],['Registered relations',record.relations],['Original source occurrences',record.sourceOccurrences]]){
      const details=el('details',undefined,'original-record');details.append(el('summary',title),el('pre',stringify(value)));target.append(details);
    }
    target.append(el('p','Deposited reference count: '+(record.referenceCount??'Not supplied'),'muted small'));
    target.scrollIntoView({block:'nearest'});
  }
  function renderRecords(){
    const records=array(local.current?.review?.records),pages=Math.max(1,Math.ceil(records.length/20));
    local.page=Math.min(local.page,pages-1);
    $('crossref-records').replaceChildren(...records.slice(local.page*20,local.page*20+20).map(record=>{
      const row=el('tr'),publication=el('td'),button=el('button',record.title,'source-title');
      button.type='button';button.addEventListener('click',()=>displayRecord(record));
      publication.append(button,el('p',record.doi,'muted small'));
      const dates=el('td');
      for(const name of ['published-online','published-print','issued'])if(record.dates?.[name])dates.append(el('div',name.replace('published-','')+': '+dateParts(record.dates[name])));
      row.append(publication,dates,el('td',fieldComparison(record.doi).label));return row;
    }));
    $('crossref-page').textContent=records.length+' records · Page '+(local.page+1)+' of '+pages;
    $('crossref-prev').disabled=local.page===0||isBusy();$('crossref-next').disabled=local.page+1===pages||isBusy();
  }
  function renderCurrent(){
    const value=local.current;$('crossref-empty').hidden=!!value;$('crossref-review-content').hidden=!value;
    if(!value)return;
    const {plan,operation}=value,review=value.review;
    $('crossref-plan-title').textContent=plan.request.label;
    $('crossref-plan-state').textContent=value.interrupted?'Interrupted — retained responses are ready to resume':operation.phase==='IMPORTED'?'Retained in dossier revision '+operation.received.revision:operation.phase;
    $('crossref-plan-question').textContent=plan.payload.question;
    $('crossref-plan-meta').textContent='Reviewed from revision '+plan.request.expectedRevision+' · '+date(plan.preparedAt)+
      ' · '+plan.payload.metadataRequests+' metadata requests'+(plan.request.includeUpdates?' and at least '+plan.payload.minimumUpdateRequests+' update requests':'')+
      ' · '+(plan.request.refresh?'Fresh provider responses':'Retained response cache enabled');
    $('crossref-dois').textContent=plan.payload.dois.join('\n');
    $('crossref-coverage').textContent=review?.coverage??'Awaiting acquisition';
    $('crossref-progress').textContent=operation.responses+' original response'+(operation.responses===1?'':'s')+' retained.'+
      (operation.lastCapture?' Latest: HTTP '+operation.lastCapture.status+' · '+operation.lastCapture.url:'')+
      (operation.received?' Edition received at '+date(operation.received.receivedAt)+'.':'');
    const warnings=[];
    if(operation.error)warnings.push(friendly(operation.error)+'.');
    if(value.sourceMatches===false)warnings.push('This operation was prepared for a different source configuration. Its retained edition remains available; create a new scope to acquire through the current configuration.');
    if(value.questionMatches===false)warnings.push('The saved question has changed. Review a new acquisition scope for that question.');
    if(review?.warnings?.length)warnings.push(...review.warnings.map(row=>friendly(row.code)+(row.dois?.length?' ('+row.dois.join(', ')+')':'')+'.'));
    problem(warnings.join(' '));
    const canStart=['PREPARED','STOPPED','FAILED'].includes(operation.phase)||value.interrupted;
    $('crossref-start').hidden=!canStart;$('crossref-start').disabled=value.sourceMatches===false||isBusy();
    $('crossref-start').textContent=operation.responses?'Resume acquisition':'Acquire metadata';
    $('crossref-stop').hidden=!value.running;$('crossref-stop').disabled=isBusy();
    $('crossref-receive').hidden=operation.phase!=='READY';
    $('crossref-receive').disabled=value.questionMatches!==true||isBusy();
    $('crossref-receive').textContent=review?.records?.length?'Retain reviewed edition':'Retain provider outcome';
    $('crossref-download').hidden=!['READY','IMPORTED'].includes(operation.phase);$('crossref-download').disabled=isBusy();
    $('crossref-result').hidden=!review;
    if(review){
      $('crossref-result-summary').textContent=review.records.length+' metadata records; '+array(review.usage.updates).length+' update collections. The comparison uses saved dossier revision '+value.currentRevision+'.';
      $('crossref-usage').textContent=stringify({coverage:review.coverage,usage:review.usage,warnings:review.warnings});
      renderRecords();
    }
    schedule();
  }
  $('crossref-plan-form').addEventListener('submit',event=>{
    event.preventDefault();withAction(async()=>{
      const view=getDossier();
      const input={questionId:$('crossref-question').value,expectedRevision:view.revision,selectedOnly:$('crossref-selected').checked,
        includeUpdates:$('crossref-updates').checked,refresh:$('crossref-fresh').checked,label:$('crossref-label').value};
      if(!local.pending||stringify(local.pending.input)!==stringify(input))savePending({requestId:crypto.randomUUID(),input});
      const result=await api(endpoint('/prepare'),{method:'POST',body:{...local.pending.input,requestId:local.pending.requestId}});
      local.current=result;local.page=0;savePending(null);$('crossref-record-detail').hidden=true;
      await loadList();await loadCurrent();notify('Review the saved DOI scope before starting acquisition.');
    },event.currentTarget);
  });
  for(const id of ['crossref-question','crossref-selected'])$(id).addEventListener('change',renderScope);
  $('crossref-refresh').addEventListener('click',()=>withAction(refresh));
  $('crossref-more').addEventListener('click',()=>withAction(()=>loadList({more:true})));
  $('crossref-start').addEventListener('click',()=>withAction(async()=>{
    local.current=await api(operationPath('/start'),{method:'POST',body:{expectedPlanSha256:local.current.plan.sha256}});
    await loadCurrent();notify('Crossref acquisition is running. Its original responses and progress are retained.');
  }));
  $('crossref-stop').addEventListener('click',()=>withAction(async()=>{
    local.current=await api(operationPath('/stop'),{method:'POST',body:{}});await loadCurrent();
    notify('Acquisition stopped. Resume this saved operation to reuse its original responses.');
  }));
  $('crossref-receive').addEventListener('click',()=>withAction(async()=>{
    const current=local.current;
    const result=await api(operationPath('/receive'),{method:'POST',body:{expectedRevision:current.currentRevision,
      expectedPlanSha256:current.plan.sha256,expectedEditionSha256:current.operation.editionSha256}});
    await onReceived(result.dossier);await loadCurrent();await loadList();
    notify('Reviewed Crossref edition retained in dossier revision '+result.receipt.revision+'.');
  }));
  $('crossref-download').addEventListener('click',()=>withAction(async()=>{
    const response=await api(operationPath('/edition'),{download:true}),blob=await response.blob(),url=URL.createObjectURL(blob);
    const link=el('a');link.href=url;link.download=local.current.plan.id+'.crossref.json';document.body.append(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
  }));
  $('crossref-prev').addEventListener('click',()=>{if(local.page>0){local.page--;renderRecords();}});
  $('crossref-next').addEventListener('click',()=>{local.page++;renderRecords();});
  window.addEventListener('beforeunload',stopPoll);
  return {
    configure(value){local.configured=value?.configured===true;local.identity=value?.identity??null;tab.hidden=!local.configured;
      $('crossref-account').textContent=local.identity?'Source account: '+local.identity.account+' · '+local.identity.mode+' provider pool':'';
      renderScope();},
    setDossier(view){
      if(view?.id!==local.dossierId){stopPoll();local.shown=false;local.dossierId=view?.id??null;local.loadVersion++;local.items=[];local.current=null;local.page=0;local.next=null;restorePending();renderList();renderCurrent();}
      local.revision=view?.revision??null;renderQuestions();
    },
    show(visible){const changed=visible!==local.shown;local.shown=visible;if(!visible)stopPoll();
      else if(changed)refresh().catch(error=>notify(friendly(error.code||error.message),'error'));else schedule();},
    updateBusy(){renderScope();renderCurrent();}
  };
}

// MIT. Original Object Buyer files in the existing managed Pipelines intake.
export function createObjectInputsPanel({root,api,task,notify,getDossier,isBusy,onPrepared}) {
  const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
  const copy=value=>JSON.parse(JSON.stringify(value));
  const initial=new URLSearchParams(location.hash.slice(1));
  const wanted=/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(initial.get('object')??'')&&
    /^[a-f0-9-]{36}$/.test(initial.get('objectSession')??'')?
    {session:initial.get('object'),sessionId:initial.get('objectSession')}:null;
  const state={id:null,epoch:0,source:null,profiles:[],provider:false,items:[],next:null,snapshot:null,
    reviews:[],reviewsNext:null,selected:wanted,review:null,busy:false,shown:false,journal:null};
  root.className='pipelines-intake';
  root.innerHTML="\n<h3>Use a completed Object Buyer file</h3>\n<p class=\"muted small\" id=\"research-object-source\"></p>\n<div class=\"button-row\"><button type=\"button\" id=\"research-object-refresh\">Read saved acquisitions</button>\n<button type=\"button\" id=\"research-object-more\" hidden>More acquisitions</button>\n<button type=\"button\" id=\"research-object-history\">Read captured reviews</button></div>\n<label>Saved acquisition<select id=\"research-object-session\"><option value=\"\">Choose a saved file</option></select></label>\n<p id=\"research-object-selection\" class=\"muted small\"></p>\n<div class=\"button-row\"><button type=\"button\" id=\"research-object-review\">Review exact delivered file</button>\n<button type=\"button\" id=\"research-object-resume\" hidden>Continue saved request</button></div>\n<p id=\"research-object-pending\" class=\"muted small\" role=\"status\"></p>\n<div id=\"research-object-reviews\" aria-label=\"Captured file reviews\"></div>\n<button type=\"button\" id=\"research-object-reviews-more\" hidden>More captured reviews</button>\n<section id=\"research-object-detail\" hidden>\n<h4>Captured original file</h4><dl id=\"research-object-facts\" class=\"pipelines-facts\"></dl>\n<details class=\"original-record\"><summary>Original acquisition reference</summary><pre id=\"research-object-reference\"></pre></details>\n<form id=\"research-object-prepare-form\"><div class=\"pipelines-fields\">\n<label>Processing profile<select id=\"research-object-profile\" required></select></label>\n<label>Research question<select id=\"research-object-question\" required></select></label>\n<label>Job label<input id=\"research-object-label\" maxlength=\"240\" required></label></div>\n<button type=\"submit\" id=\"research-object-prepare\">Save processing preparation</button><p class=\"form-error\" hidden></p>\n</form></section>\n<p class=\"muted small\">Review retains the verified delivery and its original session identity in this Research workspace.\nSaving a preparation preserves that reviewed input. Submit the original plan below when you are ready to start processing.</p>";
  const $=name=>root.querySelector('#research-object-'+name);
  const context=()=>({id:state.id,epoch:state.epoch,workspaceId:state.source?.workspaceId??null,
    sourceSha256:state.source?.sourceSha256??null});
  const live=ctx=>ctx.id===state.id&&ctx.epoch===state.epoch&&ctx.workspaceId===state.source?.workspaceId&&
    ctx.sourceSha256===state.source?.sourceSha256;
  const key=ctx=>'research-original-object:v1:'+ctx.workspaceId+':'+ctx.sourceSha256+':'+ctx.id;
  const endpoint=(ctx,suffix)=>'/api/dossiers/'+encodeURIComponent(ctx.id)+'/pipelines/'+suffix;
  function readJournal(ctx) {
    try {
      const value=JSON.parse(localStorage.getItem(key(ctx))??'null');
      if(value?.schema==='research-original-object.v1'&&value.dossierId===ctx.id&&
        value.workspaceId===ctx.workspaceId&&value.sourceSha256===ctx.sourceSha256)return value;
    }catch{}
    return {schema:'research-original-object.v1',dossierId:ctx.id,workspaceId:ctx.workspaceId,
      sourceSha256:ctx.sourceSha256,pending:null,selectedReview:null};
  }
  function save(ctx,value) {
    try{localStorage.setItem(key(ctx),JSON.stringify(value));}
    catch{if(live(ctx))notify('This browser could not save the request for a restart. Keep the displayed request ID.','error');}
    if(live(ctx))state.journal=value;
  }
  function selectOptions(select,rows,selected,placeholder) {
    select.replaceChildren(...[{id:'',label:placeholder},...rows].map(row=>{
      const option=node('option',row.label);option.value=row.id;return option;
    }));
    if(rows.some(row=>row.id===selected))select.value=selected;
  }
  function render() {
    const configured=state.source?.configured===true,pending=state.journal?.pending;
    $('source').textContent=configured?'Original Object workspace '+state.source.workspaceId+
      '. Only saved sessions from the launcher-selected workspace are available.':
      'The Research launcher can select the original Object Buyer state with --object-state.';
    const rows=state.items.filter(row=>row.sessionId).map(row=>({id:row.session,label:
      (row.name||row.session)+' · '+new Intl.NumberFormat().format(row.bytes)+' bytes'+
      (row.unavailable?' · '+row.unavailable.replaceAll('_',' ').toLowerCase():'')}));
    if(state.selected&&!rows.some(row=>row.id===state.selected.session))
      rows.unshift({id:state.selected.session,label:'Selected original session '+state.selected.session});
    selectOptions($('session'),rows,state.selected?.session,'Choose a saved acquisition');
    $('selection').textContent=state.selected?'Original session '+state.selected.sessionId:
      'Choose an acquisition, then explicitly review its recorded complete file.';
    $('more').hidden=!state.next;$('resume').hidden=!pending;
    $('pending').textContent=pending?'Saved '+pending.kind.toLowerCase()+' request '+pending.body.requestId+
      '. Continue this exact request to recover its result.':state.journal?.last?.message??'';
    $('review').textContent=pending?.kind==='REVIEW'?'Continue exact file review':'Review exact delivered file';
    $('reviews').replaceChildren(...state.reviews.map(review=>{
      const button=node('button',review.reference.filename+' · '+new Intl.NumberFormat().format(review.reference.bytes)+
        ' bytes · '+review.capturedAt,'pipelines-item');
      button.type='button';button.dataset.objectReview=review.reviewId;
      button.onclick=()=>{if(isBusy()||state.busy||state.journal?.pending)return;
        state.review=review;const ctx=context(),j=readJournal(ctx);j.selectedReview=review.reviewId;save(ctx,j);render();};
      return button;
    }));
    $('reviews-more').hidden=!state.reviewsNext;
    const review=state.review,ref=review?.reference;$('detail').hidden=!review;
    if(ref) {
      const fields=[['File',ref.filename],['Bytes',String(ref.bytes)],['SHA-256',ref.sha256],
        ['Original session',ref.sessionId],['Snapshot',ref.snapshot],['Delivery',ref.deliveryMode],
        ['Configuration',ref.configurationSha256],['Captured',review.capturedAt]];
      $('facts').replaceChildren(...fields.flatMap(([label,value])=>[node('dt',label),node('dd',value)]));
      $('reference').textContent=JSON.stringify(ref,null,2);
    }
    const saved=pending?.kind==='PREPARE'?pending.body:null;
    selectOptions($('profile'),state.profiles.map(p=>({id:p.id,label:p.label})),
      saved?.profileId??$('profile').value,'Choose a processing profile');
    const dossier=getDossier();
    selectOptions($('question'),(dossier?.id===state.id?dossier.questions:[]).map(q=>({id:q.id,label:q.text})),
      saved?.questionId??$('question').value,'Choose a research question');
    if(saved)$('label').value=saved.label;
    updateBusy();
  }
  function updateBusy(parentBusy=false) {
    const busy=parentBusy||isBusy()||state.busy||!state.id,configured=state.source?.configured===true;
    root.querySelectorAll('button,input,select').forEach(el=>{el.disabled=busy;});
    if(busy)return;
    $('refresh').disabled=!configured;$('history').disabled=!configured;
    $('more').disabled=!configured||!state.next;$('reviews-more').disabled=!configured||!state.reviewsNext;
    $('session').disabled=!configured||!!state.journal?.pending;
    const selected=state.items.find(row=>row.session===state.selected?.session);
    $('review').disabled=!configured||!state.selected||!!selected?.unavailable||state.journal?.pending?.kind==='PREPARE';
    $('resume').disabled=!configured||!state.journal?.pending;
    $('prepare').disabled=!configured||!state.provider||!state.review||!!state.journal?.pending||
      !$('profile').value||!$('question').value||!$('label').value.trim();
    for(const name of ['profile','question','label'])$(name).disabled=!state.provider||!!state.journal?.pending;
    root.querySelectorAll('[data-object-review]').forEach(el=>{el.disabled=!!state.journal?.pending;});
  }
  async function run(work,form) {
    return task(async()=>{state.busy=true;updateBusy();
      try{await work();}finally{state.busy=false;updateBusy();}
    },form);
  }
  async function inventory(more=false) {
    const ctx=context();if(!ctx.id||!state.source?.configured)return;
    const query=new URLSearchParams({limit:'25'});
    if(more&&state.next){query.set('after',state.next);query.set('snapshot',state.snapshot);}
    const result=await api(endpoint(ctx,'objects?'+query));
    if(!live(ctx))return;
    state.items=more?[...state.items,...result.items]:result.items;state.next=result.nextAfter;state.snapshot=result.snapshot;
    if(!result.available)notify('The original source is unavailable. Previously captured reviews remain usable.','error');
    render();
  }
  async function reviews(more=false) {
    const ctx=context();if(!ctx.id||!state.source?.configured)return;
    const query=new URLSearchParams({limit:'25'});if(more&&state.reviewsNext)query.set('after',state.reviewsNext);
    const result=await api(endpoint(ctx,'object-reviews?'+query));if(!live(ctx))return;
    state.reviews=more?[...state.reviews,...result.items]:result.items;state.reviewsNext=result.nextAfter;
    const selected=state.reviews.find(row=>row.reviewId===state.journal?.selectedReview);if(selected)state.review=selected;
    render();
  }
  async function dispatch(ctx,pending) {
    const j=readJournal(ctx);j.pending=copy(pending);save(ctx,j);if(live(ctx))render();
    let result;
    try{result=await api(endpoint(ctx,pending.kind==='REVIEW'?'objects/review':'objects/prepare'),
      {method:'POST',body:pending.body});}
    catch(error) {
      if(Number.isInteger(error.status)&&error.status>=400&&error.status<500&&error.status!==429) {
        const saved=readJournal(ctx);saved.pending=null;
        saved.last={requestId:pending.body.requestId,error:error.code,
          message:'Request '+pending.body.requestId+' returned '+error.code+'. Its original records remain retained.'};save(ctx,saved);
      }
      throw error;
    }
    const saved=readJournal(ctx);
    if(pending.kind==='REVIEW') {
      if(result.requestId!==pending.body.requestId||result.dossierId!==ctx.id||
        result.reference?.session!==pending.body.session||result.reference?.sessionId!==pending.body.expectedSessionId||
        result.source?.workspaceId!==ctx.workspaceId||result.source?.sourceSha256!==ctx.sourceSha256)
        throw new Error('RESEARCH_OBJECT_REVIEW_REPLY_CHANGED');
      saved.selectedReview=result.reviewId;
      if(live(ctx)){state.review=result;state.reviews=[result,...state.reviews.filter(row=>row.reviewId!==result.reviewId)];}
    } else {
      const request=result.plan?.payload?.request;
      if(request?.requestId!==pending.body.requestId||request.context?.dossierId!==ctx.id||
        request.context?.objectInput?.reviewId!==pending.body.reviewId||
        request.context?.objectInput?.reviewSha256!==pending.body.expectedReviewSha256)
        throw new Error('RESEARCH_OBJECT_PREPARATION_REPLY_CHANGED');
      saved.last={requestId:pending.body.requestId,operationId:result.plan.id,
        message:'Original processing preparation '+result.plan.id+' is saved. Review and submit its plan below.'};
    }
    saved.pending=null;save(ctx,saved);if(!live(ctx))return;
    render();
    if(pending.kind==='PREPARE')await onPrepared(result,ctx.id);
    else notify((result.replayed?'Recovered':'Captured')+' the original delivered file for review.');
  }
  $('session').onchange=()=>{
    const row=state.items.find(row=>row.session===$('session').value);
    state.selected=row?{session:row.session,sessionId:row.sessionId}:null;render();
  };
  $('review').onclick=()=>run(async()=>{
    const ctx=context(),pending=state.journal?.pending;if(pending){await dispatch(ctx,copy(pending));return;}
    if(!state.selected)return;
    await dispatch(ctx,{kind:'REVIEW',body:{requestId:'research-object-review-'+crypto.randomUUID(),
      session:state.selected.session,expectedSessionId:state.selected.sessionId}});
  });
  $('resume').onclick=()=>run(()=>state.journal?.pending?dispatch(context(),copy(state.journal.pending)):Promise.resolve());
  $('prepare-form').onsubmit=event=>{event.preventDefault();run(async()=>{
    const ctx=context(),review=state.review,dossier=getDossier();if(!review||dossier?.id!==ctx.id)return;
    await dispatch(ctx,{kind:'PREPARE',body:{requestId:'research-object-prepare-'+crypto.randomUUID(),
      profileId:$('profile').value,questionId:$('question').value,label:$('label').value,
      expectedRevision:dossier.revision,reviewId:review.reviewId,expectedReviewSha256:review.reviewSha256}});
  },event.currentTarget);};
  $('refresh').onclick=()=>run(()=>inventory());$('more').onclick=()=>run(()=>inventory(true));
  $('history').onclick=()=>run(()=>reviews());$('reviews-more').onclick=()=>run(()=>reviews(true));
  for(const name of ['profile','question','label'])$(name).oninput=()=>updateBusy();
  function reset(id) {
    state.id=id;state.epoch++;state.shown=false;state.items=[];state.next=null;state.snapshot=null;
    state.reviews=[];state.reviewsNext=null;state.review=null;
    state.journal=id&&state.source?.configured?readJournal(context()):null;$('label').value='';render();
  }
  render();
  return {
    configure(value) {
      const source=value?.objects??{configured:false},changed=source.sourceSha256!==state.source?.sourceSha256;
      state.source=source;state.provider=value?.configured===true;state.profiles=value?.source?.profiles??[];
      if(changed)reset(state.id);else render();
    },
    setDossier(view) {if((view?.id??null)!==state.id)reset(view?.id??null);else render();},
    async show(visible) {
      const changed=state.shown!==visible;state.shown=visible;
      if(visible&&changed&&state.id&&state.source?.configured) {
        state.busy=true;updateBusy();
        try{await inventory();await reviews();}catch(error){notify(error.message,'error');}
        finally{state.busy=false;updateBusy();}
      }
    },
    updateBusy,
  };
}

/* Source-bundle controls share the operator's neutral industrial palette. */
#source-bundle-dialog{width:min(880px,calc(100vw - 36px));max-height:92vh}
#source-bundle-form{display:grid;gap:14px}
.source-bundle-modes{display:flex;gap:18px;flex-wrap:wrap}
.source-bundle-modes label{display:flex;align-items:center;gap:7px}
#source-bundle-original-fields,#source-bundle-folder-fields{display:grid;gap:14px}
#source-bundle-original-fields[hidden],#source-bundle-folder-fields[hidden]{display:none}
#source-bundle-review{display:grid;gap:12px}
#source-bundle-review:empty{display:none}
#source-bundle-review details{border-top:1px solid #d5d5d5;padding-top:10px}
#source-bundle-review details p{white-space:pre-wrap}
.source-bundle-review-source{border:1px solid #d5d5d5;padding:12px;background:#fafafa}
.source-bundle-review-source p{margin:6px 0 0;overflow-wrap:anywhere}
.source-bundle-counts{font-variant-numeric:tabular-nums;color:#454545}
.source-bundle-summary{white-space:pre-wrap}
.source-bundle-file{border-top:1px solid #d5d5d5;padding:12px 0}
.source-bundle-file-heading{display:flex;gap:12px;align-items:flex-start;justify-content:space-between}
.source-bundle-file-heading>div{display:grid;gap:4px;min-width:0}
.source-bundle-file-heading strong{overflow-wrap:anywhere}
.source-bundle-file-heading button{flex-shrink:0}
.source-bundle-file details{margin-top:10px}
.source-bundle-file summary{cursor:pointer}
.source-bundle-file-text{max-height:440px;overflow:auto;white-space:pre;font:12px/1.5 ui-monospace,monospace;
  padding:12px;background:#f4f4f4;border:1px solid #d5d5d5}

// MIT. Import complete local source bundles into the selected original question.
const element=(tag,text,className)=>{
  const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);
  if(className)node.className=className;return node;
};
const size=bytes=>bytes<1024?bytes+' B':bytes<1024*1024?(bytes/1024).toFixed(1)+' KiB':(bytes/(1024*1024)).toFixed(2)+' MiB';
const sha=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');
const base64=bytes=>{
  let value='';for(let at=0;at<bytes.length;at+=32768)value+=String.fromCharCode(...bytes.subarray(at,at+32768));
  return btoa(value);
};
const decode=file=>{
  if(file.encoding==='utf8')return new TextEncoder().encode(file.content);
  const text=atob(file.content),bytes=new Uint8Array(text.length);
  for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i);return bytes;
};
function download(bytes,name,type){
  const url=URL.createObjectURL(new Blob([bytes],{type})),link=element('a');
  link.href=url;link.download=name;link.hidden=true;document.body.append(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),30000);
}
export function renderSourceBundleFiles(root,content){
  root.replaceChildren();
  const visible=content&&Array.isArray(content.files)&&content.files.length>0&&content.files.every(file=>
    file&&typeof file.name==='string'&&typeof file.content==='string'&&['utf8','base64'].includes(file.encoding));
  root.hidden=!visible;if(!visible)return false;
  if(content.summary)root.append(element('p',content.summary,'source-bundle-summary'));
  root.append(element('p',content.files.length+' original file'+(content.files.length===1?'':'s'),'muted small'));
  for(const file of content.files){
    const row=element('article',undefined,'source-bundle-file'),heading=element('div',undefined,'source-bundle-file-heading');
    const details=element('div');details.append(element('strong',file.name),element('span',size(file.bytes)+' · '+(file.mediaType??'Original file'),'muted small'));
    const button=element('button','Download','compact');button.type='button';
    button.addEventListener('click',()=>download(decode(file),file.name.split('/').at(-1),file.mediaType??'application/octet-stream'));
    heading.append(details,button);row.append(heading);
    const readable=file.encoding==='utf8'||/^(text\/|application\/(json|xml))/.test(file.mediaType??'')||
      /\.(md|txt|csv|tsv|tab|json|xml|html|svg|py|js|mjs|css)$/i.test(file.name);
    if(readable){
      const disclosure=element('details'),summary=element('summary','Read complete text');disclosure.append(summary);
      disclosure.addEventListener('toggle',()=>{
        disclosure.querySelector('pre')?.remove();
        if(disclosure.open){
          let text;try{text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(decode(file));}
          catch{text='This original file uses another text encoding. Download it to open with the appropriate reader.';}
          disclosure.append(element('pre',text,'source-bundle-file-text'));
        }
      });row.append(disclosure);
    }
    root.append(row);
  }return true;
}
export function createSourceBundlePanel({root,openButton,api,task,notify,getDossier,isBusy,onReceived}){
  const $=id=>root.querySelector('#'+id),form=$('source-bundle-form');
  let reviewed=null,preparedText=null,editVersion=0,currentDossierId=null;
  const selectedMode=()=>form.querySelector('[name=sourceBundleMode]:checked').value;
  const invalidate=()=>{
    reviewed=null;preparedText=null;editVersion++;$('source-bundle-review').replaceChildren();
    $('source-bundle-receive').disabled=true;$('source-bundle-save-file').disabled=true;
  };
  const mode=()=>{
    invalidate();const folder=selectedMode()==='folder';
    $('source-bundle-original-fields').hidden=folder;$('source-bundle-folder-fields').hidden=!folder;
  };
  const fillQuestions=()=>{
    const selected=$('source-bundle-question').value,view=getDossier();
    $('source-bundle-question').replaceChildren(...(view?.questions??[]).map(question=>{
      const option=element('option',question.text);option.value=question.id;return option;
    }));
    if((view?.questions??[]).some(q=>q.id===selected))$('source-bundle-question').value=selected;
    $('source-bundle-empty').hidden=Boolean(view?.questions?.length);
    $('source-bundle-preview').disabled=isBusy()||!view?.questions?.length;
  };
  const originalFile=async(file,name=file.name)=>{
    const bytes=new Uint8Array(await file.arrayBuffer());
    return {name,bytes:bytes.length,sha256:await sha(bytes),encoding:'base64',
      mediaType:file.type||'application/octet-stream',content:base64(bytes)};
  };
  async function sourceText(){
    if(selectedMode()==='bundle'){
      const file=$('source-bundle-file').files[0];
      if(!file)throw new Error('Choose a source bundle file.');
      if(file.size>64*1024*1024)throw new Error('The source bundle exceeds 64 MiB.');
      return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());
    }
    const manifestFile=$('source-bundle-manifest').files[0],selected=Array.from($('source-bundle-folder').files);
    if(!manifestFile||!selected.length)throw new Error('Choose the source manifest and its original folder.');
    if(manifestFile.size>1024*1024)throw new Error('The source manifest exceeds 1 MiB.');
    const manifestOriginal=await originalFile(manifestFile);
    const manifest=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(decode(manifestOriginal)));
    if(manifest.schema!=='sf88-research-source-manifest-v1'||!Array.isArray(manifest.sources))
      throw new Error('Choose a research source manifest.');
    const wanted=new Set(manifest.sources.flatMap(source=>source.files??[])),available=new Map();
    for(const file of selected){
      const full=file.webkitRelativePath||file.name;
      const relative=file.webkitRelativePath?full.slice(full.indexOf('/')+1):full;
      if(available.has(relative))throw new Error('Two selected files have the same relative name: '+relative);
      available.set(relative,file);
    }
    let total=0;const files=[];
    for(const name of wanted){
      const file=available.get(name);if(!file)throw new Error('The selected folder is missing '+name);
      total+=file.size;if(total>48*1024*1024)throw new Error('The selected original files exceed 48 MiB.');
      files.push(await originalFile(file,name));
    }
    const rawText=JSON.stringify({schema:'sf88-research-source-bundle-v1',manifest,manifestOriginal,files})+'\n';
    if(new TextEncoder().encode(rawText).length>64*1024*1024)throw new Error('The complete source bundle exceeds 64 MiB.');
    return rawText;
  }
  function renderReview(result){
    const target=$('source-bundle-review');target.replaceChildren();
    target.append(element('h3',result.label),element('p',result.fileCount+' files · '+size(result.fileBytes)+
      ' · '+result.sources.length+' sources · '+result.findings.length+' findings','source-bundle-counts'));
    const terms=element('details');terms.append(element('summary','Source terms'),element('p',result.sourceTerms));target.append(terms);
    for(const source of result.sources){
      const row=element('article',undefined,'source-bundle-review-source');
      row.append(element('strong',source.title),element('p',source.fileCount+' files · '+
        (source.selected?'Selected evidence':'Available source')+' · '+source.classification,'muted small'));
      if(source.url||source.doi)row.append(element('p',source.doi||source.url,'muted small'));
      if(source.note)row.append(element('p',source.note));
      target.append(row);
    }
    for(const finding of result.findings){
      const row=element('details');row.append(element('summary',finding.title),element('p',finding.text),
        element('p','Sources: '+finding.sourceKeys.join(', '),'muted small'));target.append(row);
    }
    if(result.alreadyReceived)target.append(element('p','This complete bundle is already saved in this question. Import will reopen its current saved result.'));
  }
  $('source-bundle-preview').addEventListener('click',()=>task(async()=>{
    const version=editVersion,view=getDossier(),questionId=$('source-bundle-question').value;
    if(!view||!questionId)throw new Error('Add or select a research question first.');
    const rawText=await sourceText();
    const result=await api('/api/dossiers/'+encodeURIComponent(view.id)+'/source-bundles/preview',
      {method:'POST',body:{questionId,rawText}});
    if(version!==editVersion||getDossier()?.id!==view.id||$('source-bundle-question').value!==questionId)return;
    reviewed={...result,dossierId:view.id,questionId};preparedText=rawText;
    renderReview(result);updateBusy();notify('Source bundle ready: '+result.fileCount+' files and '+result.findings.length+' findings.');
  },form));
  form.addEventListener('submit',event=>{
    event.preventDefault();
    task(async()=>{
      if(!reviewed||!preparedText)throw new Error('Choose and preview the source bundle first.');
      const saved=reviewed,rawText=preparedText,version=editVersion;
      if(getDossier()?.id!==saved.dossierId||$('source-bundle-question').value!==saved.questionId)
        throw new Error('The selected research question changed. Preview the bundle for this question.');
      const view=await api('/api/dossiers/'+encodeURIComponent(saved.dossierId)+'/source-bundles/receive',
        {method:'POST',body:{questionId:saved.questionId,rawText,expectedRevision:saved.expectedRevision,
          expectedBundleSha256:saved.bundleSha256}});
      await onReceived(view);
      if(version===editVersion){root.close();invalidate();}
      notify(saved.fileCount+' original files and '+saved.findings.length+' findings saved together.');
    },form);
  });
  $('source-bundle-save-file').addEventListener('click',()=>{
    if(preparedText)download(new TextEncoder().encode(preparedText),'research-sources.json','application/json');
  });
  form.querySelectorAll('input,select').forEach(input=>input.addEventListener('change',
    ()=>input.name==='sourceBundleMode'?mode():invalidate()));
  function updateBusy(){
    $('source-bundle-preview').disabled=isBusy()||!getDossier()?.questions?.length;
    $('source-bundle-receive').disabled=isBusy()||!reviewed;
    $('source-bundle-save-file').disabled=isBusy()||!preparedText;
  }
  openButton.addEventListener('click',()=>{
    if(isBusy()||!getDossier())return;
    fillQuestions();root.showModal();updateBusy();
  });
  return {setDossier(view){
    if(view?.id!==currentDossierId){currentDossierId=view?.id??null;invalidate();}
    fillQuestions();updateBusy();
  },updateBusy};
}

// MIT. Read selected original source bytes only when the analyst opens or downloads them.
const element=(tag,text,className)=>{
  const value=document.createElement(tag);if(text!==undefined)value.textContent=String(text);
  if(className)value.className=className;return value;
};
const size=bytes=>bytes<1024?bytes+' B':bytes<1024*1024?(bytes/1024).toFixed(1)+' KiB':(bytes/(1024*1024)).toFixed(2)+' MiB';
const digest=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),
  value=>value.toString(16).padStart(2,'0')).join('');
const route=(dossierId,selection,part,revision,parameters={})=>{
  const query=new URLSearchParams({revision:String(revision),...parameters});
  return '/api/dossiers/'+encodeURIComponent(dossierId)+'/retained-editions/'+encodeURIComponent(selection.editionId)+
    '/occurrences/'+encodeURIComponent(selection.key)+'/'+part+'?'+query;
};
async function originalBytes(api,path,expectedSha256,expectedBytes){
  const response=await api(path,{download:true}),bytes=new Uint8Array(await response.arrayBuffer());
  if(expectedBytes!==undefined&&bytes.length!==expectedBytes||await digest(bytes)!==expectedSha256)
    throw Object.assign(new Error('The selected original file changed.'),{code:'RESEARCH_SOURCE_FILE_CHANGED'});
  return {bytes,type:response.headers.get('content-type')??'application/octet-stream'};
}
function download(bytes,name,type){
  const url=URL.createObjectURL(new Blob([bytes],{type})),link=element('a');
  link.href=url;link.download=name;link.hidden=true;document.body.append(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),30000);
}
function button(label,action,task){
  const value=element('button',label,'compact');value.type='button';
  value.addEventListener('click',()=>task(action));return value;
}
export function renderOriginalRecordControl({root,citation,dossierId,revision,api,task,notify}){
  const record=citation.originalRecord;
  if(!record||!citation.retained)return;
  root.append(button('Download original result record',async()=>{
    const value=await originalBytes(api,route(dossierId,citation,'record',revision,{sha256:record.sha256}),record.sha256,record.bytes);
    download(value.bytes,citation.editionId+'-'+citation.key+'-record.json',value.type);
    notify('Original result record downloaded.');
  },task));
}
/** Returns true when the source uses the explicit compact inspection contract. */
export function renderInspectedSource({filesRoot,excerpt,source,variant,dossierId,revision,api,task,notify}){
  const inspection=variant?variant.inspection:source.inspection;
  if(inspection?.schema!=='sf88-research-source-inspection-v1')return false;
  filesRoot.replaceChildren();filesRoot.hidden=false;
  const content=variant?variant.content:source.content,selection=inspection.selection;
  const files=inspection.files??[];
  excerpt.hidden=files.length>0;
  if(!files.length){
    excerpt.textContent=content===null||content===undefined?
      'Full structured content is available as a JSON download.':
      typeof content==='string'?content:JSON.stringify(content,null,2);
    excerpt.classList.toggle('typed-content',content!==null&&typeof content==='object');
    if(!inspection.complete)filesRoot.append(element('p','Preview · complete content '+size(inspection.bytes),'muted small'));
  }else{
    if(content?.summary)filesRoot.append(element('p',content.summary,'source-bundle-summary'));
    filesRoot.append(element('p',files.length+' original file'+(files.length===1?'':'s'),'muted small'));
  }
  if(!selection?.retained){
    filesRoot.append(element('p','Open this source through its original provider edition.','muted small'));
    return true;
  }
  for(const file of files){
    const row=element('article',undefined,'source-bundle-file'),heading=element('div',undefined,'source-bundle-file-heading');
    const details=element('div');details.append(element('strong',file.name),
      element('span',size(file.bytes)+' · '+(file.mediaType??'Original file'),'muted small'));
    const fileRoute=route(dossierId,selection,'file',revision,{name:file.name,sha256:file.sha256});
    const actions=element('div',undefined,'button-row');
    actions.append(button('Download',async()=>{
      const value=await originalBytes(api,fileRoute,file.sha256,file.bytes);
      download(value.bytes,file.name.split('/').at(-1),value.type);notify('Downloaded '+file.name+'.');
    },task));
    const readable=file.encoding==='utf8'||/^(text\/|application\/(json|xml))/.test(file.mediaType??'')||
      /\.(md|txt|csv|tsv|tab|json|xml|html|svg|py|js|mjs|css)$/i.test(file.name);
    if(readable){
      let opened=false;
      actions.append(button('Read text',async()=>{
        const prior=row.querySelector('pre');
        if(opened){prior?.remove();opened=false;return;}
        const value=await originalBytes(api,fileRoute,file.sha256,file.bytes);
        let text;
        try{text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(value.bytes);}
        catch{notify('Download this file to open its original text encoding.');return;}
        row.append(element('pre',text,'source-bundle-file-text'));opened=true;
      },task));
    }
    heading.append(details,actions);row.append(heading);filesRoot.append(row);
  }
  filesRoot.append(button(files.length?'Download content JSON':'Download complete content',async()=>{
    const value=await originalBytes(api,route(dossierId,selection,'content',revision,{sha256:inspection.sha256}),
      inspection.sha256,inspection.bytes);
    download(value.bytes,selection.editionId+'-'+selection.key+'-content.'+
      (inspection.representation==='text'?'txt':'json'),value.type);
    notify('Complete source content downloaded.');
  },task));
  return true;
}

