  if(stateFile&&existsSync(stateFile)){
    const bytes=readFileSync(stateFile);assert(bytes.length<2*1024*1024);
    restored=JSON.parse(bytes);
    assert.equal(restored.schema,'stellar-forge.managed-pipelines-native-provider-state.v1');
    assert.equal(restored.scenarioSha256,scenarioSha256);assert.equal(restored.pathPrefix,pathPrefix);
    assert(Array.isArray(restored.jobs)&&restored.jobs.length<=2&&Array.isArray(restored.records)&&Array.isArray(restored.errors));
    for(const [index,record] of restored.jobs.entries()){
      assert.equal(typeof record.id,'string');
      assert(['SCHEDULED','IN_PROGRESS','COMPLETED','STOPPED'].includes(record.status));
      assert.deepEqual(record.inputs,index===0?scenario.inputs:scenario.inputs.slice(0,1));
      assert.equal(record.inputIds.length,record.inputs.length);
    }
  }
  const jobs=new Map((restored?.jobs??[]).map(record=>[record.id,record]));
  const records=restored?.records??[],errors=restored?.errors??[];
  const counters=restored?.counters??{create:0,list:0,get:0,details:0,cancel:0,download:0};
  for(const count of Object.values(counters))assert(Number.isSafeInteger(count)&&count>=0);
  assert.equal(counters.create,jobs.size);
  const creates=restored?.creates??[],clockId=randomUUID();
  let closed=false;
  function persist(){
    if(!stateFile)return;
    const state={schema:'stellar-forge.managed-pipelines-native-provider-state.v1',
      scenarioSha256,pathPrefix,jobs:[...jobs.values()],records,errors,counters,creates};
    const temporary=stateFile+'.'+randomUUID()+'.tmp';let fd;
    try{
      fd=openSync(temporary,'wx',0o600);writeFileSync(fd,JSON.stringify(state)+'\n');fsyncSync(fd);closeSync(fd);fd=undefined;
      renameSync(temporary,stateFile);const directory=openSync(dirname(stateFile),'r');try{fsyncSync(directory);}finally{closeSync(directory);}
    }finally{if(fd!==undefined)closeSync(fd);try{unlinkSync(temporary);}catch(error){if(error.code!=='ENOENT')throw error;}}
  }
  const jobRoot=pathPrefix+'api/v1/jobs/';
  function information(record) {
    return {
      id:record.id,workflow_id:record.workflowId,workflow_name:'Local-file partition fixture',
      status:record.status,created_at:record.createdAt,job_type:'ephemeral',
      runtime:record.status==='COMPLETED'?'0:00:01':null,
      // Deliberately independent of local input order. Consumers select these IDs.
      input_file_ids:[...record.inputIds].reverse(),
      output_node_files:record.status==='COMPLETED'?[{
        node_id:record.nodeId,file_id:record.nodeFileId,node_type:'partition',node_subtype:'unstructured_api',
      }]:[],
    };
  }
  function details(record) {
    const count=record.inputIds.length;
    return {id:record.id,
      processing_status:record.status==='COMPLETED'?'SUCCESS':record.status,
      message:record.status==='STOPPED'?'Stopped after the configured cancel request':null,
      node_stats:[{
        node_name:'Partition local files',node_type:'partition',node_subtype:'unstructured_api',
        ready:record.status==='SCHEDULED'?count:0,
        in_progress:record.status==='IN_PROGRESS'?count:0,
        success:record.status==='COMPLETED'?count:0,failure:0,
      }],
    };
  }
  function output(record,fileId,nodeId) {
    assert.equal(record.status,'COMPLETED','A provider output is available after this fixture completes');
    if(nodeId===null) {
      const index=record.inputIds.indexOf(fileId);
      assert(index>=0,'Default output file ID must come from the actual provider job');
      return Buffer.from(JSON.stringify(elements(record.inputs[index],index),null,2)+'\n');
    }
    assert.equal(nodeId,record.nodeId);assert.equal(fileId,record.nodeFileId);
    return Buffer.from(JSON.stringify(elements(record.inputs[0],0,{intermediate:true}),null,2)+'\n');
  }
  async function handle(req,res) {
    assert(!closed,'Fixture is closed');
    const url=new URL(req.url,'https://fixture.invalid');
    assert.equal(req.headers['unstructured-api-key'],apiKey,'Selected provider account must authenticate every request');
    assert.equal(req.headers.accept,'application/json');
    const observed={method:req.method,path:url.pathname,query:Object.fromEntries(url.searchParams),
      receivedAt:new Date().toISOString(),authenticated:true};
    records.push(observed);
    if(req.method==='POST'&&url.pathname===jobRoot) {
      assert.equal(url.search,'');
      const raw=await requestBytes(req,128*1024);
      const request=new Request('https://fixture.invalid'+url.pathname,
        {method:'POST',headers:req.headers,body:raw});
      const form=await request.formData();
      assert.deepEqual([...new Set(form.keys())].sort(),['input_files','request_data']);
      const data=form.getAll('request_data');
      assert.equal(data.length,1);assert.equal(typeof data[0],'string');
      const requestData=JSON.parse(data[0]);
      assert.deepEqual(requestData,scenario.profile.requestData);
      const files=form.getAll('input_files');
      assert(files.length>=1&&files.length<=10);
      const current=counters.create;
      assert(current<2,'This one native journey prepares exactly two original provider jobs');
      const expected=current===0?scenario.inputs:scenario.inputs.slice(0,1);
      assert.equal(files.length,expected.length);
      const captured=[];
      for(let index=0;index<files.length;index++){
        const file=files[index],wanted=expected[index],body=Buffer.from(await file.arrayBuffer());
        assert.equal(file.name,wanted.filename);assert.equal(file.type,wanted.contentType);
        assert.deepEqual(body,Buffer.from(wanted.text,'utf8'));
        captured.push({filename:file.name,contentType:file.type,bytes:body.length,sha256:digest(body)});
      }
      const launched=process.hrtime.bigint(),previous=creates.at(-1);
      const interval=previous?.clockId===clockId?Number(launched-BigInt(previous.monotonicNs))/1e6:null;
      if(interval!==null)assert(interval>=1000,
        'The original same-account launch gate must preserve the service one-second interval');
      creates.push({clockId,monotonicNs:String(launched),receivedAt:new Date().toISOString(),intervalMs:interval});counters.create++;
      const id=randomUUID(),record={
        id,workflowId:randomUUID(),createdAt:new Date().toISOString(),status:current===0?'SCHEDULED':'IN_PROGRESS',
        inputs:clone(expected),inputIds:expected.map(()=>randomUUID()),
        nodeId:randomUUID(),nodeFileId:randomUUID(),cancelAcknowledged:false,
      };
      jobs.set(id,record);
      Object.assign(observed,{jobId:id,requestDataSha256:digest(Buffer.from(data[0])),
        inputs:captured,response:current===0?'connection-lost-after-create':'200'});
      persist(); // Provider identity exists durably before either the lost response or the acknowledgement.
      if(current===0){res.destroy();return;}
      json(res,200,information(record));return;
    }
    if(req.method==='GET'&&url.pathname===jobRoot) {
      assert([...url.searchParams.keys()].every(k=>['workflow_id','status'].includes(k)));
      counters.list++;
      const rows=[...jobs.values()].filter(row=>
        (!url.searchParams.has('workflow_id')||row.workflowId===url.searchParams.get('workflow_id'))&&
        (!url.searchParams.has('status')||row.status===url.searchParams.get('status')));
      json(res,200,rows.map(information));return;
    }
    assert(url.pathname.startsWith(jobRoot),'Use the selected API path prefix');
    const parts=url.pathname.slice(jobRoot.length).split('/');
    assert(parts.length===1||parts.length===2);
    const id=decodeURIComponent(parts[0]),record=jobs.get(id);
    assert(record,'Read or control the retained original provider job ID');
    observed.jobId=id;
    if(req.method==='GET'&&parts.length===1) {
      assert.equal(url.search,'');counters.get++;observed.providerStatus=record.status;
      json(res,200,information(record));return;
    }
    if(req.method==='GET'&&parts[1]==='details') {
      assert.equal(url.search,'');counters.details++;json(res,200,details(record));return;
    }
    if(req.method==='POST'&&parts[1]==='cancel') {
      assert.equal(url.search,'');
      assert.equal((await requestBytes(req,1)).length,0);
      assert.equal(record.status,'IN_PROGRESS');
      assert.equal(record.cancelAcknowledged,false,'A local request replay must not submit cancel twice');
      record.cancelAcknowledged=true;counters.cancel++;persist();
      // The acknowledgement alone is not STOPPED. The next getter still observes IN_PROGRESS.
      json(res,200,{});return;
    }
    if(req.method==='GET'&&parts[1]==='download') {
      assert([...url.searchParams.keys()].every(k=>['file_id','node_id'].includes(k)));
      assert.equal(url.searchParams.getAll('file_id').length,1);
      assert(url.searchParams.getAll('node_id').length<=1);
      const fileId=url.searchParams.get('file_id'),nodeId=url.searchParams.get('node_id');
      const body=output(record,fileId,nodeId);counters.download++;
      Object.assign(observed,{fileId,nodeId,outputBytes:body.length,outputSha256:digest(body)});
      res.writeHead(200,{'content-type':'application/json','content-length':body.length,
        'x-request-id':'local-output-'+randomUUID()});res.end(body);return;
    }
    assert.fail('Unsupported method or endpoint in the declared official Jobs lifecycle');
  }
  return Object.freeze({
    handler(req,res){handle(req,res).catch(error=>{
      errors.push({at:new Date().toISOString(),code:error.code??'FIXTURE_CONTRACT_ERROR',message:error.message});
      if(!res.headersSent)json(res,500,{detail:'Retained fixture contract mismatch'});
      else res.destroy();
    }).finally(()=>{try{persist();}catch(error){errors.push({code:error.code??'FIXTURE_STATE_WRITE_FAILED',message:error.message});}});},
    inputs(){return scenario.inputs.map(file=>({...metadata(file),body:Buffer.from(file.text,'utf8')}));},
    jobs(){return [...jobs.values()].map(information);},
    job(id){const value=jobs.get(id);assert(value);return information(value);},
    complete(id){const value=jobs.get(id);assert(value);assert.equal(value.status,'SCHEDULED');value.status='COMPLETED';persist();return information(value);},
    confirmStop(id){const value=jobs.get(id);assert(value?.cancelAcknowledged);assert.equal(value.status,'IN_PROGRESS');value.status='STOPPED';persist();return information(value);},
    output(id,fileId,nodeId=null){const value=jobs.get(id);assert(value);return output(value,fileId,nodeId);},
    summary(){return {schema:'stellar-forge.managed-pipelines-fixture-result.v1',
      providerMode:scenario.providerMode,providerContract:clone(scenario.providerContract),
      scenarioSha256,inputs:scenario.inputs.map(metadata),
      counters:clone(counters),jobs:[...jobs.values()].map(information),requests:clone(records),
      launchIntervalsMs:creates.slice(1).map(value=>value.intervalMs),errors:clone(errors)};},
    close(){persist();closed=true;},
  });
}

// MIT. Sole-caller entry for the retained managed Pipelines native browser journey.
// Run only through the already selected native resource operation.
import assert from 'node:assert/strict';
import { createServer } from 'node:https';
import { readFile, mkdir, mkdtemp, realpath, stat, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { existsSync, readFileSync, writeFileSync, openSync, closeSync, fsyncSync, renameSync } from 'node:fs';
import { join, resolve, dirname, isAbsolute, relative } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawn, execFileSync } from 'node:child_process';
import { createHash, randomBytes, randomUUID } from 'node:crypto';
import { createPipelineJobFixture, PIPELINE_NATIVE_SCENARIO } from './managed-pipelines-fixture.mjs';
import { runManagedPipelineBrowserJourney } from './managed-pipelines-browser.mjs';

const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const gitBlob=bytes=>createHash('sha1').update(Buffer.from('blob '+bytes.length+'\0')).update(bytes).digest('hex');
function options(argv){
  assert.equal(argv.length%2,0,'Each native option requires its selected value');
  const result={};
  for(let index=0;index<argv.length;index+=2){
    const name=argv[index],value=argv[index+1];
    assert(['--source-root','--source-identity-file','--directory','--output','--playwright','--chromium','--temporary-root','--private-runtime'].includes(name));
    assert(!Object.hasOwn(result,name));assert(isAbsolute(value)&&resolve(value)===value);
    result[name]=value;
  }
  for(const name of ['--source-root','--source-identity-file','--directory','--output','--playwright','--chromium'])assert(result[name],name+' is required');
  return result;
}
function privateJson(path,value){
  const temporary=path+'.'+randomUUID()+'.tmp';
  const fd=openSync(temporary,'wx',0o600);
  try{writeFileSync(fd,JSON.stringify(value,null,2)+'\n');fsyncSync(fd);}finally{closeSync(fd);}
  renameSync(temporary,path);const directory=openSync(dirname(path),'r');try{fsyncSync(directory);}finally{closeSync(directory);}
}
async function checkedSource(root,path){
  const bytes=await readFile(path),declared=JSON.parse(bytes.toString('utf8'));
  assert.equal(declared.schema,'stellar-forge.native-source-selection.v1');
  assert.equal(declared.repository,'woahwhattheheck/public-commons-sprint-2026');
  assert(declared.files&&typeof declared.files==='object'&&!Array.isArray(declared.files));
  if(declared.commit!==undefined)assert(/^[a-f0-9]{40}$/.test(declared.commit));
  const actual={};
  for(const [name,pin] of Object.entries(declared.files)){
    assert(name&&!isAbsolute(name)&&!name.split('/').some(part=>part==='..'||part===''||part==='.'));
    assert(pin&&/^[a-f0-9]{40}$/.test(pin.gitBlob));
    const selected=resolve(root,name);assert(!relative(root,selected).startsWith('..'));
    const body=await readFile(selected),observed={gitBlob:gitBlob(body),sha256:hash(body),bytes:body.length};
    assert.equal(observed.gitBlob,pin.gitBlob,'Selected native source changed: '+name);
    if(pin.sha256!==undefined)assert.equal(observed.sha256,pin.sha256);
    actual[name]=observed;
  }
  for(const required of [
    'sf88-operator-buyer-cli/research-dossiers/server.mjs',
    'sf88-operator-buyer-cli/research-dossiers/dossier.mjs',
    'sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines-workspace.mjs',
    'sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines/contract.mjs',
    'sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines/client.mjs',
    'sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines/operations.mjs',
    'sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines/edition.mjs',
    'sf88-operator-buyer-cli/research-dossiers/public/app.js',
    'sf88-operator-buyer-cli/research-dossiers/public/index.html',
    'sf88-operator-buyer-cli/research-dossiers/public/unstructured-pipelines.js',
    'sf88-operator-buyer-cli/research-dossiers/public/unstructured-pipelines.css',
  ])assert(Object.hasOwn(actual,required),'The actual joined source selection must include '+required);
  return {schema:declared.schema,repository:declared.repository,...(declared.commit?{commit:declared.commit}:{}),
    selectionFileSha256:hash(bytes),files:actual};
}

/**
 * The outer process creates only process-private TLS/browser material, then starts
 * the same selected command in a child whose native fetch trusts that original CA.
 * Persistent provider/job/receiving state stays in the selected native directory.
 */
export async function runManagedPipelineNative(argv){
  const selected=options(argv);
  const temporaryRoot=await realpath(selected['--temporary-root']??(process.platform==='linux'?'/dev':tmpdir()));
  assert((await stat(temporaryRoot)).isDirectory(),'The selected temporary root must be an existing directory');
  if(!selected['--private-runtime']){
    const privateRuntime=await mkdtemp(join(temporaryRoot,'b9d2-managed-pipelines-'));
    try{
      const key=join(privateRuntime,'provider-key.pem'),certificate=join(privateRuntime,'provider-cert.pem');
      execFileSync('openssl',['req','-x509','-newkey','rsa:2048','-nodes','-days','1',
        '-keyout',key,'-out',certificate,'-subj','/CN=localhost',
        '-addext','subjectAltName=IP:127.0.0.1,DNS:localhost'],{stdio:['ignore','ignore','pipe']});
      const code=await new Promise((accept,reject)=>{
        // Pin the outer temporary root: the child's TMPDIR points at its private runtime.
        const temporaryArguments=selected['--temporary-root']?[]:['--temporary-root',temporaryRoot];
        const child=spawn(process.execPath,[fileURLToPath(import.meta.url),...argv,...temporaryArguments,'--private-runtime',privateRuntime],{
          stdio:'inherit',env:{...process.env,NODE_EXTRA_CA_CERTS:certificate,TMPDIR:privateRuntime},
        });
        child.once('error',reject);child.once('exit',(code,signal)=>accept(code??(signal?1:0)));
      });
      return code;
    }finally{await rm(privateRuntime,{recursive:true,force:true});}
  }
  const privateRuntime=selected['--private-runtime'];
  assert(dirname(privateRuntime)===temporaryRoot&&privateRuntime.startsWith(join(temporaryRoot,'b9d2-managed-pipelines-')));
  assert.equal(await realpath(privateRuntime),privateRuntime);
  const sourceRoot=selected['--source-root'],directory=selected['--directory'],output=selected['--output'];
  assert(directory!==sourceRoot&&!directory.startsWith(sourceRoot+'/'));
  assert(output!==sourceRoot&&!output.startsWith(sourceRoot+'/'));
  await mkdir(directory,{recursive:true,mode:0o700});await mkdir(output,{recursive:true,mode:0o700});
  const identity=await checkedSource(sourceRoot,selected['--source-identity-file']);
  const hostPath=join(directory,'host-state.json');
  const previous=existsSync(hostPath)?JSON.parse(readFileSync(hostPath)):null;
  if(previous){
    assert.equal(previous.schema,'stellar-forge.managed-pipelines-native-host.v1');
    assert.equal(previous.sourceSelectionSha256,identity.selectionFileSha256);
  }
  const workspaceId=previous?.workspaceId??'managed-pipelines-native-'+randomUUID();
  // A new private token can serve the same configured API-key variable. Its value is never retained.
  const apiKey=randomBytes(32).toString('hex');
  const fixture=createPipelineJobFixture({apiKey,pathPrefix:'/enterprise/',
    stateFile:join(output,'provider-state.json')});
  const server=createServer({key:await readFile(join(privateRuntime,'provider-key.pem')),
    cert:await readFile(join(privateRuntime,'provider-cert.pem'))},fixture.handler);
  let app,context,operations;
  try{
    await new Promise((accept,reject)=>{server.once('error',reject);server.listen(previous?.providerPort??0,'127.0.0.1',accept);});
    const providerPort=server.address().port;
    const configuration={
      schema:'stellar-forge.unstructured-pipelines-config.v1',
      account:'retained-native-local-provider',apiUrl:'https://127.0.0.1:'+providerPort+'/enterprise/',
      apiKeyEnv:'B9D2_NATIVE_PIPELINE_API_KEY',profiles:[PIPELINE_NATIVE_SCENARIO.profile],
      limits:{maxInputs:10,maxInputBytes:50000000,maxTotalInputBytes:33554432,
        maxRequestDataBytes:1048576,maxResponseBytes:1048576,maxOutputBytes:1048576,requestTimeoutMs:15000},
    };
    privateJson(hostPath,{schema:'stellar-forge.managed-pipelines-native-host.v1',
      providerPort,workspaceId,sourceSelectionSha256:identity.selectionFileSha256});
    const module=path=>import(pathToFileURL(join(sourceRoot,path)).href);
    const [{openPipelineOperations},{startDossierWorkspace},playwright]=await Promise.all([
      module('sf88-operator-buyer-cli/research-dossiers/unstructured-pipelines/operations.mjs'),
      module('sf88-operator-buyer-cli/research-dossiers/server.mjs'),
      import(pathToFileURL(selected['--playwright']).href),
    ]);
    const providerDirectory=join(directory,'provider-operations');
    operations=await openPipelineOperations({directory:providerDirectory,configuration,
      env:{B9D2_NATIVE_PIPELINE_API_KEY:apiKey}});
    app=await startDossierWorkspace({directory:join(directory,'dossiers'),pipelineSource:{
      operations,workspaceId,directory:providerDirectory,
    }});
    context=await playwright.chromium.launchPersistentContext(join(privateRuntime,'browser'),{
      executablePath:selected['--chromium'],headless:true,acceptDownloads:true,
      viewport:{width:1440,height:1000},args:['--no-sandbox','--disable-dev-shm-usage'],
      env:{...process.env,TMPDIR:privateRuntime},
    });
    const page=context.pages()[0]??await context.newPage();
    const result=await runManagedPipelineBrowserJourney({
      page,app,fixture,outputDirectory:output,sourceIdentity:identity,
      openRestoredWorkspace:()=>startDossierWorkspace({directory:join(directory,'restored-dossiers'),pipelineSource:null}),
    });
    assert.deepEqual(await checkedSource(sourceRoot,selected['--source-identity-file']),identity);
    privateJson(join(output,'native-host-result.json'),{
      schema:'stellar-forge.managed-pipelines-native-host-result.v1',status:result.status,
      sourceIdentity:identity,nodeVersion:process.version,opensslVersion:process.versions.openssl,
      providerMode:PIPELINE_NATIVE_SCENARIO.providerMode,
      outputDirectory:output,originalOperation:result.operationId,
      providerJobId:result.providerJobId,editionIds:result.editionIds,
    });
    process.stdout.write(JSON.stringify({status:result.status,outputDirectory:output,
      resultFile:join(output,'managed-pipelines-result.json'),originalOperation:result.operationId,
      providerJobId:result.providerJobId,providerCounters:result.providerCounters})+'\n');
    return 0;
  }finally{
    await context?.close().catch(()=>{});
    await app?.close().catch(()=>{});
    await operations?.close().catch(()=>{});
    fixture.close();
    await new Promise(accept=>{server.close(accept);server.closeAllConnections();});
  }
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{process.exitCode=await runManagedPipelineNative(process.argv.slice(2));}
  catch(error){process.stderr.write(JSON.stringify({code:error.code??'MANAGED_PIPELINES_NATIVE_FAILED',message:error.message})+'\n');process.exitCode=1;}
}

import type { Buffer } from 'node:buffer';
import type {
  Json, JsonObject, PipelineConfiguration, PipelineLimits, PipelineSource, SourceIdentity, ProfileSummary,
  ProviderJob, ProviderDetails, PipelineOutputOption, JobStatus,
} from './contract.mjs';
export type OperationPhase = 'PREPARED' | 'SUBMITTING' | 'SUBMISSION_UNKNOWN' | 'REJECTED' | 'ACTIVE' | 'COMPLETED' | 'STOPPED' | 'FAILED';
export type ActionKind = 'submit' | 'refresh' | 'cancel' | 'reconcile' | 'retain';
export interface PipelineInputSelection {
  path: string; filename: string; contentType?: string; sourceRef?: Json;
}
export interface PipelineInput {
  id: string; index: number; filename: string; contentType: string;
  bytes: number; sha256: string; file: string; sourceRef?: Json;
}
export interface PipelineOutput {
  id: string; providerJobId: string; fileId: string; nodeId: string | null;
  selectionSource: 'input_file_ids' | 'output_node_files'; label: string;
  bytes: number; sha256: string; contentType: string; receivedAt: string; receiptId: string; file: string;
}
export interface PipelinePlan {
  schema: 'stellar-forge.unstructured-pipelines-plan.v1'; id: string; sha256: string;
  requestSha256: string; preparedAt: string;
  payload: {
    request: { requestId: string; profileId: string; label: string; context: JsonObject };
    source: SourceIdentity; profile: ProfileSummary; inputs: PipelineInput[]; limits: PipelineLimits;
    providerContract: { repository: string; commit: string; version: string; openapiVersion: string };
  };
}
export interface PipelineError {
  code: string; action: string; at: string;
  status?: number; receiptId?: string; interrupted?: boolean;
}
export interface ActionResult {
  requestId: string; kind: ActionKind; status: 'COMPLETE'; appliedRevision: number;
  result: { outputId?: string }; error: PipelineError | null;
}
export interface PipelineOperation {
  schema: 'stellar-forge.unstructured-pipelines-operation.v1'; id: string; revision: number;
  phase: OperationPhase; providerJobId: string | null; job: ProviderJob | null; details: ProviderDetails | null;
  outputs: PipelineOutput[];
  cancel: null | {
    requestId: string; reason: string; requestedAt: string;
    status: 'ACKNOWLEDGED' | 'UNKNOWN' | 'REJECTED' | 'CONFIRMED'; receiptId: string | null; confirmedAt?: string;
  };
  reconciliation: null | { requestId: string; providerJobId: string; reason: string; selectedAt: string; receiptId: string };
  pendingCommandId: string | null;
  activeAction: null | { commandId: string; requestId: string; kind: ActionKind; startedAt: string };
  lastAction: null | { commandId: string; requestId: string; kind: ActionKind; finishedAt: string;
    result: { outputId?: string }; error: PipelineError | null };
