      !Number.isInteger(concurrency) || concurrency < 1 || concurrency > 16 ||
      !Number.isInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 60000)
    throw new RangeError('Invalid delivery batch, concurrency or timeout');
